async def _prospecto_queries_cache_size() -> int:
    async with _PROSPECTO_QUERIES_CACHE_LOCK:
        return len(_PROSPECTO_QUERIES_CACHE)


async def _clear_prospecto_queries_cache() -> None:
    async with _PROSPECTO_QUERIES_CACHE_LOCK:
        _PROSPECTO_QUERIES_CACHE.clear()


async def _get_prospecto_queries_inflight_future(
    cache_key: str,
) -> tuple[asyncio.Future[dict[str, Any]], bool]:
    async with _PROSPECTO_QUERIES_INFLIGHT_LOCK:
        existing = _PROSPECTO_QUERIES_INFLIGHT.get(cache_key)
        if existing is not None:
            return existing, False
        loop = asyncio.get_running_loop()
        created: asyncio.Future[dict[str, Any]] = loop.create_future()
        _PROSPECTO_QUERIES_INFLIGHT[cache_key] = created
        return created, True


async def _release_prospecto_queries_inflight_future(
    cache_key: str,
    future: asyncio.Future[dict[str, Any]],
) -> None:
    async with _PROSPECTO_QUERIES_INFLIGHT_LOCK:
        current = _PROSPECTO_QUERIES_INFLIGHT.get(cache_key)
        if current is future:
            _PROSPECTO_QUERIES_INFLIGHT.pop(cache_key, None)


def _percentile(values: list[float], percentile: float) -> float:
    if not values:
        return 0.0
    rank = max(0, min(len(values) - 1, math.ceil((percentile / 100) * len(values)) - 1))
    return values[rank]


async def _record_inbox_threads_metrics(*, duration_ms: float, cache_hit: bool) -> None:
    now = time.monotonic()
    async with _INBOX_THREADS_METRICS_LOCK:
        global _INBOX_THREADS_METRICS_CACHE_HITS, _INBOX_THREADS_METRICS_CACHE_MISSES, _INBOX_THREADS_METRICS_SLOW_QUERIES
        _INBOX_THREADS_METRICS_SAMPLES.append((now, max(0.0, duration_ms)))
        if cache_hit:
            _INBOX_THREADS_METRICS_CACHE_HITS += 1
        else:
            _INBOX_THREADS_METRICS_CACHE_MISSES += 1
        if duration_ms > 3000:
            _INBOX_THREADS_METRICS_SLOW_QUERIES += 1
        cutoff = now - INBOX_THREADS_METRICS_WINDOW_SECONDS
        while _INBOX_THREADS_METRICS_SAMPLES and _INBOX_THREADS_METRICS_SAMPLES[0][0] < cutoff:
            _INBOX_THREADS_METRICS_SAMPLES.popleft()
    await high_demand_controller.record_inbox_threads_latency(latency_ms=duration_ms)


async def _record_inbox_threads_stage_metrics(*, stage_timings: dict[str, float]) -> None:
    if not stage_timings:
        return
    now = time.monotonic()
    normalized: dict[str, float] = {}
    for key, value in stage_timings.items():
        if not isinstance(key, str):
            continue
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            continue
        if numeric < 0:
            continue
        normalized[key] = numeric
    if not normalized:
        return
    async with _INBOX_THREADS_METRICS_LOCK:
        _INBOX_THREADS_STAGE_METRICS_SAMPLES.append((now, normalized))
        cutoff = now - INBOX_THREADS_METRICS_WINDOW_SECONDS
        while _INBOX_THREADS_STAGE_METRICS_SAMPLES and _INBOX_THREADS_STAGE_METRICS_SAMPLES[0][0] < cutoff:
            _INBOX_THREADS_STAGE_METRICS_SAMPLES.popleft()


async def _snapshot_inbox_threads_metrics(*, window_seconds: int) -> dict[str, Any]:
    now = time.monotonic()
    cutoff = now - window_seconds
    async with _INBOX_THREADS_METRICS_LOCK:
        samples = [duration for ts, duration in _INBOX_THREADS_METRICS_SAMPLES if ts >= cutoff]
        ordered = sorted(samples)
        stage_samples = [payload for ts, payload in _INBOX_THREADS_STAGE_METRICS_SAMPLES if ts >= cutoff]
        cache_hits = _INBOX_THREADS_METRICS_CACHE_HITS
        cache_misses = _INBOX_THREADS_METRICS_CACHE_MISSES
        slow_queries = _INBOX_THREADS_METRICS_SLOW_QUERIES

    stage_values: dict[str, list[float]] = {}
    for sample in stage_samples:
        for stage_name, metric_value in sample.items():
            stage_values.setdefault(stage_name, []).append(metric_value)
    stage_latency_ms: dict[str, dict[str, float]] = {}
    for stage_name, values in stage_values.items():
        ordered_stage = sorted(values)
        stage_latency_ms[stage_name] = {
            "p50": round(_percentile(ordered_stage, 50), 2),
            "p90": round(_percentile(ordered_stage, 90), 2),
            "p95": round(_percentile(ordered_stage, 95), 2),
            "max": round(ordered_stage[-1], 2) if ordered_stage else 0.0,
            "avg": round((sum(ordered_stage) / len(ordered_stage)), 2) if ordered_stage else 0.0,
            "count": len(ordered_stage),
        }

    total = cache_hits + cache_misses
    hit_rate = (cache_hits / total) if total else 0.0
    return {
        "window_seconds": window_seconds,
        "sample_count": len(ordered),
        "latency_ms": {
            "p50": round(_percentile(ordered, 50), 2),
            "p90": round(_percentile(ordered, 90), 2),
            "p95": round(_percentile(ordered, 95), 2),
            "max": round(ordered[-1], 2) if ordered else 0.0,
            "avg": round((sum(ordered) / len(ordered)), 2) if ordered else 0.0,
        },
        "cache": {
            "hits": cache_hits,
            "misses": cache_misses,
            "hit_rate": round(hit_rate, 4),
        },
        "slow_queries_over_3000ms": slow_queries,
        "stage_latency_ms": stage_latency_ms,
    }


async def _record_prospectos_process_metrics(
    *,
    endpoint: str,
    duration_ms: float,
    flags: dict[str, Any] | None = None,
) -> None:
    now = time.monotonic()
    normalized_flags: dict[str, Any] = {}
    for key, value in (flags or {}).items():
        if not isinstance(key, str):
            continue
        if isinstance(value, bool):
            normalized_flags[key] = value
            continue
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            normalized_flags[key] = float(value)
            continue
    async with _PROSPECTOS_PROCESS_METRICS_LOCK:
        _PROSPECTOS_PROCESS_METRICS_SAMPLES.append(
            (
                now,
                str(endpoint or "unknown"),
                max(0.0, float(duration_ms)),
                normalized_flags,
            )
        )
        cutoff = now - INBOX_THREADS_METRICS_WINDOW_SECONDS
        while _PROSPECTOS_PROCESS_METRICS_SAMPLES and _PROSPECTOS_PROCESS_METRICS_SAMPLES[0][0] < cutoff:
            _PROSPECTOS_PROCESS_METRICS_SAMPLES.popleft()


async def _snapshot_prospectos_process_metrics(*, window_seconds: int) -> dict[str, Any]:
    now = time.monotonic()
    cutoff = now - window_seconds
    async with _PROSPECTOS_PROCESS_METRICS_LOCK:
        samples = [
            (endpoint, duration, flags)
            for ts, endpoint, duration, flags in _PROSPECTOS_PROCESS_METRICS_SAMPLES
            if ts >= cutoff
        ]

    endpoints: dict[str, dict[str, Any]] = {}
    for endpoint, duration, flags in samples:
        bucket = endpoints.setdefault(
            endpoint,
            {
                "durations": [],
                "slow_queries_over_3000ms": 0,
                "flag_counts": {},
            },
        )
        durations = bucket["durations"]
        durations.append(duration)
        if duration > 3000:
            bucket["slow_queries_over_3000ms"] += 1
        flag_counts = bucket["flag_counts"]
        for key, value in flags.items():
            if isinstance(value, bool):
                if value:
                    flag_counts[key] = int(flag_counts.get(key, 0)) + 1
            elif isinstance(value, (int, float)):
                flag_counts[key] = float(flag_counts.get(key, 0.0)) + float(value)

    normalized_endpoints: dict[str, Any] = {}
    for endpoint, bucket in endpoints.items():
        durations = sorted(bucket["durations"])
        normalized_endpoints[endpoint] = {
            "request_count": len(durations),
            "latency_ms": {
                "p50": round(_percentile(durations, 50), 2),
                "p90": round(_percentile(durations, 90), 2),
                "p95": round(_percentile(durations, 95), 2),
                "max": round(durations[-1], 2) if durations else 0.0,
                "avg": round((sum(durations) / len(durations)), 2) if durations else 0.0,
            },
            "slow_queries_over_3000ms": int(bucket["slow_queries_over_3000ms"]),
            "flags": bucket["flag_counts"],
        }

    return {
        "window_seconds": window_seconds,
        "sample_count": len(samples),
        "endpoints": normalized_endpoints,
    }


async def _snapshot_owner_metrics(*, window_seconds: int) -> dict[str, Any]:
    inbox_snapshot = await _snapshot_inbox_threads_metrics(window_seconds=window_seconds)
    process_snapshot = await _snapshot_prospectos_process_metrics(window_seconds=window_seconds)
    return {
        **inbox_snapshot,
        "process_metrics": process_snapshot,
    }


async def _capture_inbox_threads_snapshot_entry(
    *,
    window_seconds: int,
    actor_user_id: str | None,
) -> dict[str, Any]:
    snapshot = await _snapshot_owner_metrics(window_seconds=window_seconds)
    entry = {
        "captured_at": datetime.now(timezone.utc).isoformat(),
        "window_seconds": window_seconds,
        "actor_user_id": actor_user_id,
        "snapshot": snapshot,
    }
    _append_inbox_threads_metrics_snapshot(entry)
    return entry


class InboxThreadsMetricsSnapshotRunner:
    """Guarda snapshots periódicos de métricas de Inbox threads en logs."""

    def __init__(self, *, interval_minutes: int = 5, window_seconds: int = 300) -> None:
        self._interval_seconds = max(60, interval_minutes * 60)
        self._window_seconds = max(60, window_seconds)
        self._task: asyncio.Task[None] | None = None
        self._stop = asyncio.Event()

    async def start(self) -> None:
        if self._task and not self._task.done():
            return
        self._stop = asyncio.Event()
        self._task = asyncio.create_task(self._run_loop(), name="inbox-threads-metrics-snapshot")
        logger.info(
            "crm.inbox.threads.metrics.runner_started",
            extra={
                "interval_seconds": self._interval_seconds,
                "window_seconds": self._window_seconds,
            },
        )

    async def shutdown(self) -> None:
        self._stop.set()
        if self._task:
            await self._task
            self._task = None
        logger.info("crm.inbox.threads.metrics.runner_stopped")

    async def _run_loop(self) -> None:
        while not self._stop.is_set():
            try:
                entry = await _capture_inbox_threads_snapshot_entry(
                    window_seconds=self._window_seconds,
                    actor_user_id="system:auto_runner",
                )
                snapshot = entry.get("snapshot") if isinstance(entry, dict) else {}
                logger.info(
                    "crm.inbox.threads.metrics.auto_snapshot_saved",
                    extra={
                        "window_seconds": self._window_seconds,
                        "sample_count": (
                            snapshot.get("sample_count") if isinstance(snapshot, dict) else None
                        ),
                    },
                )
            except Exception as exc:  # pragma: no cover - defensivo
                logger.warning(
                    "crm.inbox.threads.metrics.auto_snapshot_failed",
                    extra={"error": str(exc)},
                )
            try:
                await asyncio.wait_for(self._stop.wait(), timeout=self._interval_seconds)
            except asyncio.TimeoutError:
                continue


inbox_threads_metrics_snapshot_runner = InboxThreadsMetricsSnapshotRunner(
    interval_minutes=5,
    window_seconds=300,
)


class InboxSnapshotRefreshRunner:
    """Refresca periódicamente la MV de snapshot de Inbox."""

    def __init__(self, *, interval_minutes: int = 3) -> None:
        self._interval_seconds = max(60, interval_minutes * 60)
        self._task: asyncio.Task[None] | None = None
        self._stop = asyncio.Event()

    async def start(self) -> None:
        if self._task and not self._task.done():
            return
        self._stop = asyncio.Event()
        self._task = asyncio.create_task(self._run_loop(), name="inbox-snapshot-mv-refresh")
        logger.info(
            "crm.inbox.snapshot_mv.runner_started",
            extra={"interval_seconds": self._interval_seconds},
        )

    async def shutdown(self) -> None:
        self._stop.set()
        if self._task:
            await self._task
            self._task = None
        logger.info("crm.inbox.snapshot_mv.runner_stopped")

    async def _run_loop(self) -> None:
        while not self._stop.is_set():
            started = time.perf_counter()
            try:
                repo = CRMRepository()
                await repo.refresh_inbox_conversation_snapshot_mv()
                duration_ms = round((time.perf_counter() - started) * 1000, 2)
                logger.info(
                    "crm.inbox.snapshot_mv.refresh_ok",
                    extra={"duration_ms": duration_ms},
                )
            except Exception as exc:  # pragma: no cover - defensivo
                logger.warning(
                    "crm.inbox.snapshot_mv.refresh_failed",
                    extra={"error": str(exc)},
                )
            try:
                await asyncio.wait_for(self._stop.wait(), timeout=self._interval_seconds)
            except asyncio.TimeoutError:
                continue


inbox_snapshot_refresh_runner = InboxSnapshotRefreshRunner(interval_minutes=3)


def _write_mapbox_debug_log(tag: str, payload: Any) -> None:
    try:
        MAPBOX_LOG_DIR.mkdir(parents=True, exist_ok=True)
        with MAPBOX_LOG_FILE.open("a", encoding="utf-8") as handle:
            timestamp = datetime.utcnow().isoformat()
            handle.write(f"{timestamp} | {tag} | {json.dumps(payload, default=str)}\n")
    except Exception as exc:  # pragma: no cover - best-effort logging
        logger.debug("mapbox_debug_log_failed", extra={"tag": tag, "error": str(exc)})


def _write_propiedad_sale_log(entry: dict[str, Any]) -> None:
    try:
        MAPBOX_LOG_DIR.mkdir(parents=True, exist_ok=True)
        with SALE_LOG_FILE.open("a", encoding="utf-8") as handle:
            timestamp = datetime.utcnow().isoformat()
            record = {"timestamp": timestamp, **entry}
            handle.write(f"{json.dumps(record, default=str)}\n")
    except Exception as exc:  # pragma: no cover - best-effort logging
        logger.debug("propiedad_sale_log_failed", extra={"error": str(exc), "entry": entry})


