async def _run_catalog_reindex(
    organizacion_id: UUID,
    *,
    usuario_id: str | None = None,
    canal: str | None = None,
) -> None:
    """Reindexa por completo la vector store del catálogo para el tenant especificado."""
    logger.info(
        "vector_store.reindex.triggered",
        extra={"organizacion_id": str(organizacion_id)},
    )
    repo = CRMRepository()
    service = CatalogEmbeddingService(repo)
    status = "success"
    error_detail: str | None = None
    try:
        await service.reindex_catalog(organizacion_id)
        logger.info(
            "vector_store.reindex.completed",
            extra={"organizacion_id": str(organizacion_id)},
        )
    except Exception as exc:  # pragma: no cover - logging de errores de servicio externo
        status = "failed"
        error_detail = str(exc)
        logger.exception(
            "vector_store.reindex.failed",
            extra={"organizacion_id": str(organizacion_id), "error": str(exc)},
        )
    finally:
        await service.audit_event(
            organizacion_id,
            "reindex",
            usuario_id=usuario_id,
            canal=canal,
            metadata={"status": status, "error": error_detail},
        )


async def _run_catalog_reindex_entity(
    organizacion_id: UUID,
    *,
    entity_type: Literal["linea", "familia", "modelo", "producto"],
    entity_id: UUID,
    usuario_id: str | None = None,
    canal: str | None = None,
) -> None:
    logger.info(
        "vector_store.reindex_entity.triggered",
        extra={
            "organizacion_id": str(organizacion_id),
            "entity_type": entity_type,
            "entity_id": str(entity_id),
        },
    )
    repo = CRMRepository()
    service = CatalogEmbeddingService(repo)
    status = "success"
    error_detail: str | None = None
    result: str | None = None
    try:
        result = await service.reindex_entity(
            organizacion_id,
            entity_type=entity_type,
            entity_id=entity_id,
        )
        logger.info(
            "vector_store.reindex_entity.completed",
            extra={
                "organizacion_id": str(organizacion_id),
                "entity_type": entity_type,
                "entity_id": str(entity_id),
                "result": result,
            },
        )
    except Exception as exc:  # pragma: no cover - logging de errores externos
        status = "failed"
        error_detail = str(exc)
        logger.exception(
            "vector_store.reindex_entity.failed",
            extra={
                "organizacion_id": str(organizacion_id),
                "entity_type": entity_type,
                "entity_id": str(entity_id),
                "error": str(exc),
            },
        )
    finally:
        await service.audit_event(
            organizacion_id,
            "reindex",
            usuario_id=usuario_id,
            canal=canal,
            metadata={
                "status": status,
                "error": error_detail,
                "mode": "incremental",
                "entity_type": entity_type,
                "entity_id": str(entity_id),
                "result": result,
            },
        )


def _stage_code_is_ready(code: str | None) -> bool:
    if not code:
        return False
    normalized = code.strip().lower()
    return any(token in normalized for token in OPPORTUNITY_SALE_STAGE_TOKENS)


async def _ensure_opportunity_ready_for_sale(
    repo: CRMRepository,
    organizacion_id: UUID,
    opportunity_id: UUID,
    usuario_id: UUID | None = None,
) -> dict[str, Any]:
    opportunity = await repo.get_opportunity_with_stage(
        organizacion_id=organizacion_id,
        opportunity_id=opportunity_id,
    )
    if not opportunity:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="opportunity_not_found")
    stage = opportunity.get("etapa") or {}
    codigo = stage.get("codigo")
    sale_logger.info(
        "propiedad_opportunity_stage_check",
        extra={
            "organizacion_id": str(organizacion_id),
            "oportunidad_id": str(opportunity_id),
            "stage_codigo": codigo,
            "stage_id": str(stage.get("id")) if stage.get("id") else None,
        },
    )
    _write_propiedad_sale_event(
        "opportunity_stage_check",
        {
            "organizacion_id": str(organizacion_id),
            "oportunidad_id": str(opportunity_id),
            "stage_codigo": codigo,
            "stage_id": str(stage.get("id")) if stage.get("id") else None,
        },
    )
    if not _stage_code_is_ready(codigo):
        target_stage = await _find_preferred_sale_stage(repo, organizacion_id)
        if not target_stage:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail=f"opportunity_stage_not_ready:{codigo or 'unknown'}",
            )
        target_stage_id = _safe_uuid(target_stage.get("id"))
        if not target_stage_id:
            raise HTTPException(
                status_code=status.HTTP_502_BAD_GATEWAY,
                detail="sale_stage_invalid",
            )
        try:
            opportunity = await repo.update_opportunity(
                organizacion_id=organizacion_id,
                oportunidad_id=opportunity_id,
                payload={"etapa_id": str(target_stage_id)},
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        current_stage_id = _safe_uuid(stage.get("id"))
        history_payload: dict[str, Any] = {
            "oportunidad_id": str(opportunity_id),
            "etapa_destino_id": str(target_stage_id),
            "fuente": "venta_mapbox",
        }
        if current_stage_id:
            history_payload["etapa_origen_id"] = str(current_stage_id)
        if usuario_id:
            history_payload["cambiado_por_usuario_id"] = str(usuario_id)
        await repo.append_stage_history(
            organizacion_id=organizacion_id,
            payload={k: v for k, v in history_payload.items() if v is not None},
        )
        sale_logger.info(
            "propiedad_opportunity_stage_advanced",
            extra={
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(opportunity_id),
                "stage_from_codigo": codigo,
                "stage_to_codigo": target_stage.get("codigo"),
                "stage_to_id": str(target_stage_id),
            },
        )
        _write_propiedad_sale_event(
            "opportunity_stage_advanced",
            {
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(opportunity_id),
                "stage_from_codigo": codigo,
                "stage_to_codigo": target_stage.get("codigo"),
                "stage_to_id": str(target_stage_id),
            },
        )
    return opportunity


async def _find_winning_stage(
    repo: CRMRepository,
    organizacion_id: UUID,
) -> dict[str, Any] | None:
    for code in WINNING_STAGE_CODES:
        stage = await repo.get_pipeline_stage_by_code(
            organizacion_id=organizacion_id,
            code=code,
        )
        if stage:
            return stage
    stages = await repo.list_pipelines(organizacion_id=organizacion_id)
    for stage in stages:
        if not isinstance(stage, dict):
            continue
        stage_code = (stage.get("codigo") or "").lower()
        if "ganado" in stage_code:
            return stage
    return None


async def _find_preferred_sale_stage(
    repo: CRMRepository,
    organizacion_id: UUID,
) -> dict[str, Any] | None:
    for code in SALE_TARGET_STAGE_CODES:
        stage = await repo.get_pipeline_stage_by_code(
            organizacion_id=organizacion_id,
            code=code,
        )
        if stage:
            return stage
    stages = await repo.list_pipelines(organizacion_id=organizacion_id)
    for stage in stages:
        if not isinstance(stage, dict):
            continue
        codigo = (stage.get("codigo") or "").lower()
        if _stage_code_is_ready(codigo):
            return stage
    return None


async def _advance_opportunity_to_won(
    repo: CRMRepository,
    organizacion_id: UUID,
    oportunidad_id: UUID,
    current_stage_id: UUID | None,
    usuario_id: UUID | None = None,
) -> None:
    stage = await _find_winning_stage(repo, organizacion_id)
    if not stage:
        return
    next_stage_id = _safe_uuid(stage.get("id"))
    if not next_stage_id or next_stage_id == current_stage_id:
        return
    try:
        await repo.update_opportunity(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
            payload={"etapa_id": str(next_stage_id)},
        )

        history_payload: dict[str, Any] = {
            "oportunidad_id": str(oportunidad_id),
            "etapa_origen_id": str(current_stage_id) if current_stage_id else None,
            "etapa_destino_id": str(next_stage_id),
            "fuente": "venta_mapbox",
        }
        if usuario_id:
            history_payload["cambiado_por_usuario_id"] = str(usuario_id)
        await repo.append_stage_history(
            organizacion_id=organizacion_id,
            payload={k: v for k, v in history_payload.items() if v is not None},
        )
        sale_logger.info(
            "propiedad_opportunity_marked_won",
            extra={
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "stage_destino_id": str(next_stage_id),
                "stage_destino_codigo": stage.get("codigo"),
            },
        )
        _write_propiedad_sale_event(
            "opportunity_marked_won",
            {
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "stage_destino_id": str(next_stage_id),
                "stage_destino_codigo": stage.get("codigo"),
            },
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "crm.sale_stage_advance_failed",
            extra={
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "error": str(exc),
            },
        )
        sale_logger.warning(
            "propiedad_opportunity_winning_failed",
            extra={
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "stage_destino_id": str(next_stage_id) if next_stage_id else None,
                "error": str(exc),
            },
        )
        _write_propiedad_sale_event(
            "opportunity_winning_failed",
            {
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "stage_destino_id": str(next_stage_id) if next_stage_id else None,
                "error": str(exc),
            },
        )


async def _render_quote_pdf_after_sale(
    repo: CRMRepository,
    organizacion_id: UUID,
    quote_id: UUID,
    oportunidad_id: UUID,
    usuario_id: UUID | None = None,
) -> None:
    try:
        quote_row = await repo.get_quote_entry(
            organizacion_id=organizacion_id,
            quote_id=quote_id,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "quote_entry_fetch_failed_after_sale",
            extra={
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote_id),
                "error": str(exc),
            },
        )
        return
    try:
        opportunity = await repo.get_opportunity_with_contact(
            organizacion_id=organizacion_id,
            oportunidad_id=oportunidad_id,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "opportunity_fetch_failed_for_pdf",
            extra={
                "organizacion_id": str(organizacion_id),
                "oportunidad_id": str(oportunidad_id),
                "quote_id": str(quote_id),
                "error": str(exc),
            },
        )
        return
    contact = opportunity.get("contacto") or {}
    subtotal_value = _as_number(quote_row.get("subtotal"))
    impuestos_value = _as_number(quote_row.get("impuestos"))
    total_value = _as_number(quote_row.get("total"))
    items_list = quote_row.get("items") or []
    conceptos = _concepts_from_items(items_list if isinstance(items_list, list) else [])
    reference = str(oportunidad_id).split("-")[0]
    quote_context = quotes_service.QuoteRenderContext(
        lead_label=_clean_text(
            opportunity.get("titulo")
            or contact.get("company_name")
            or contact.get("nombre_completo")
        )
        or "Cotización",
        reference=reference,
        issuer_name=settings.mail_username or "Tal-IA",
        issuer_email=settings.mail_username,
        contact_name=_clean_text(contact.get("nombre_completo")),
        contact_company=_clean_text(contact.get("company_name")),
        contact_email=_clean_text(contact.get("correo")),
        contact_phone=_clean_text(contact.get("telefono_e164")),
        conceptos=conceptos,
        subtotal=subtotal_value,
        impuestos=impuestos_value,
        total=total_value,
        moneda=_clean_text(quote_row.get("moneda") or "MXN") or "MXN",
        valido_hasta=_parse_date(quote_row.get("valida_hasta")),
        descripcion=_clean_text(opportunity.get("descripcion") or opportunity.get("titulo")),
        notes=_clean_text(contact.get("notes") or opportunity.get("metadata", {}).get("notas")),
        items=items_list if isinstance(items_list, list) else [],
    )
    try:
        pdf_doc = await quotes_service.render_quote_pdf(quote_context)
    except Exception as exc:  # pragma: no cover - best effort
        logger.warning(
            "quote_pdf_render_failed",
            extra={"quote_id": str(quote_id), "error": str(exc)},
        )
        return
    try:
        upload = await storage.upload_quote_document(
            content=pdf_doc.content,
            filename=pdf_doc.filename,
            lead_id=str(oportunidad_id),
        )
    except StorageError as exc:
        logger.warning(
            "quote_pdf_upload_failed",
            extra={"quote_id": str(quote_id), "error": str(exc)},
        )
        return
    metadata_patch = {
        "pdf_url": upload["url"],
        "pdf_path": upload["path"],
        "pdf_generated_en": datetime.now(timezone.utc).isoformat(),
    }
    if usuario_id:
        metadata_patch["pdf_generado_por"] = str(usuario_id)
    try:
        await repo.mark_quote_entry(
            organizacion_id=organizacion_id,
            quote_id=quote_id,
            metadata_patch=metadata_patch,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "quote_metadata_patch_failed",
            extra={
                "quote_id": str(quote_id),
                "organizacion_id": str(organizacion_id),
                "error": str(exc),
            },
        )


async def _mark_quote_as_accepted_from_mapbox(
    repo: CRMRepository,
    organizacion_id: UUID,
    quote_id: UUID,
    usuario_id: UUID | None = None,
) -> None:
    metadata_patch: dict[str, Any] = {
        "canal_envio": "mapbox",
        "marcada_en": datetime.now(timezone.utc).isoformat(),
    }
    if usuario_id:
        metadata_patch["marcada_por"] = str(usuario_id)
    try:
        quote_row = await repo.mark_quote_entry(
            organizacion_id=organizacion_id,
            quote_id=quote_id,
            estatus="aceptada",
            metadata_patch=metadata_patch,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "quote_mark_from_mapbox_failed",
            extra={
                "organizacion_id": str(organizacion_id),
                "quote_id": str(quote_id),
                "error": str(exc),
            },
        )
        return
    quote = _quote_from_row(quote_row)
    event_payload = {
        "organizacion_id": str(organizacion_id),
        "quote_id": str(quote_id),
        "oportunidad_id": str(quote.oportunidad_id) if quote.oportunidad_id else None,
        "canal_envio": metadata_patch["canal_envio"],
        "estatus": "aceptada",
    }
    if usuario_id:
        event_payload["usuario_id"] = str(usuario_id)
    sale_logger.info(
        "propiedad_quote_marked_from_mapbox",
        extra=event_payload,
    )
    _write_propiedad_sale_event("quote_marked_from_mapbox", event_payload)
    if quote.oportunidad_id:
        await _auto_move_opportunity_to_won(
            repo=repo,
            organizacion_id=organizacion_id,
            oportunidad_id=UUID(str(quote.oportunidad_id)),
            quote=quote,
        )


async def _ensure_product_for_catalog_item(
    repo: CRMRepository,
    organizacion_id: UUID,
    catalog_item_id: UUID,
) -> dict[str, Any]:
    catalog_item = await repo.get_catalog_item(
        organizacion_id=organizacion_id,
        item_id=catalog_item_id,
    )
    if not catalog_item:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="catalog_item_not_found")
    product = await repo.get_product(
        organizacion_id=organizacion_id,
        product_id=catalog_item_id,
    )
    if product:
        return product
    metadata = _ensure_dict(
        catalog_item.get("metadatos") or catalog_item.get("metadata") or {},
        default={},
    )
    metadata["catalog_item_id"] = str(catalog_item_id)
    codigo = (catalog_item.get("slug") or catalog_item.get("nombre") or str(catalog_item_id)).strip()
    if not codigo:
        codigo = str(catalog_item_id)
    payload: dict[str, Any] = {
        "id": str(catalog_item_id),
        "codigo": codigo,
        "nombre": catalog_item.get("nombre") or "Producto inmobiliario",
        "descripcion": catalog_item.get("descripcion_corta")
        or catalog_item.get("descripcion_larga")
        or catalog_item.get("descripcion")
        or None,
        "precio_base": _coerce_optional_number(catalog_item.get("precio_base")),
        "moneda": (catalog_item.get("moneda") or "MXN").strip().upper()[:3],
        "activo": bool(catalog_item.get("activo") is not False),
        "metadata": metadata,
    }
    familia_id = catalog_item.get("familia_id")
    if isinstance(familia_id, str) and familia_id.strip():
        payload["familia_id"] = familia_id.strip()
    modelo_id = catalog_item.get("modelo_id")
    if isinstance(modelo_id, str) and modelo_id.strip():
        payload["modelo_id"] = modelo_id.strip()
    product = await repo.create_product(
        organizacion_id=organizacion_id,
        payload=payload,
    )
    return product


def _trigger_catalog_reindex(
    background_tasks: BackgroundTasks,
    organizacion_value: Any | None,
    *,
    usuario_id: UUID | None = None,
    canal: str | None = None,
) -> None:
    """Programa la reindexación completa en segundo plano."""
    if not organizacion_value:
        return
    try:
        organizacion_id = UUID(str(organizacion_value))
    except (TypeError, ValueError):
        logger.warning(
            "vector_store.reindex.invalid_organizacion_id",
            extra={"value": organizacion_value},
        )
        return
    background_tasks.add_task(
        _run_catalog_reindex,
        organizacion_id,
        usuario_id=str(usuario_id) if usuario_id else None,
        canal=canal,
    )


def _trigger_catalog_reindex_entity(
    background_tasks: BackgroundTasks,
    organizacion_value: Any | None,
    *,
    entity_type: Literal["linea", "familia", "modelo", "producto"],
    entity_id_value: Any | None,
    usuario_id: UUID | None = None,
    canal: str | None = None,
) -> None:
    if not organizacion_value or not entity_id_value:
        return
    try:
        organizacion_id = UUID(str(organizacion_value))
        entity_id = UUID(str(entity_id_value))
    except (TypeError, ValueError):
        logger.warning(
            "vector_store.reindex_entity.invalid_payload",
            extra={
                "organizacion_id": organizacion_value,
                "entity_type": entity_type,
                "entity_id": entity_id_value,
            },
        )
        return
    background_tasks.add_task(
        _run_catalog_reindex_entity,
        organizacion_id,
        entity_type=entity_type,
        entity_id=entity_id,
        usuario_id=str(usuario_id) if usuario_id else None,
        canal=canal,
    )


def _normalize_metadata_value(value: Any) -> dict[str, Any] | None:
    if isinstance(value, Mapping):
        return {str(key): val for key, val in value.items() if val is not None}
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return None
        if isinstance(parsed, Mapping):
            return {str(key): val for key, val in parsed.items() if val is not None}
    return None


def _coerce_optional_number(value: Any) -> float | None:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _extract_metadata_from_content(content: str) -> dict[str, Any] | None:
    if not content:
        return None
    marker = "Metadata:"
    index = content.find(marker)
    if index == -1:
        return None
    start = content.find("{", index + len(marker))
    if start == -1:
        return None
    depth = 0
    end = None
    for pos in range(start, len(content)):
        char = content[pos]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                end = pos + 1
                break
    if end is None:
        return None
    snippet = content[start:end]
    try:
        metadata = json.loads(snippet)
    except json.JSONDecodeError:
        return None
    if isinstance(metadata, Mapping):
        return {str(key): val for key, val in metadata.items() if val is not None}
    return None




def _map_delete_exception(
    exc: CRMRepositoryError,
    *,
    not_found_key: str,
    dependency_key: str,
    dependency_message: str,
) -> tuple[str, int]:
    text = str(exc)
    if dependency_key in text:
        return dependency_message, status.HTTP_409_CONFLICT
    if not_found_key in text:
        return not_found_key, status.HTTP_404_NOT_FOUND
    return text, status.HTTP_502_BAD_GATEWAY


def _extract_demo_booking_id(metadata: dict[str, Any]) -> str | None:
    """Obtiene el booking_id registrado en metadata.stage_prep.demo."""
    stage_prep = _ensure_dict(metadata.get("stage_prep"), default={})
    raw_demo = stage_prep.get("demo")
    if not isinstance(raw_demo, dict):
        return None
    booking_value = raw_demo.get("demo_booking_id")
    if isinstance(booking_value, str):
        trimmed = booking_value.strip()
        return trimmed or None
    return None


