class DeleteResultadosPayload(BaseModel):
    """IDs de resultados a eliminar."""

    model_config = ConfigDict(extra="forbid")

    ids: list[UUID] = Field(
        ...,
        min_length=1,
        max_length=500,
        description="IDs de resultados (uuid) a eliminar.",
    )
    busqueda_id: UUID | None = Field(default=None, description="Busqueda activa para borrar solo apariciones.")

    @field_validator("ids")
    @classmethod
    def _dedupe_ids(cls, value: list[UUID]) -> list[UUID]:
        seen: set[UUID] = set()
        deduped: list[UUID] = []
        for item in value:
            if item in seen:
                continue
            seen.add(item)
            deduped.append(item)
        return deduped


