def _first_state_from_payload(payload: DenueBusquedaPayload) -> str | None:
    if payload.geo_estados:
        return str(payload.geo_estados[0]).zfill(2)
    if payload.geo_municipios:
        first = payload.geo_municipios[0]
        parts = first.split("::")
        if parts:
            return parts[0].zfill(2)
    return None


def _first_municipality_from_payload(payload: DenueBusquedaPayload) -> str | None:
    if not payload.geo_municipios:
        return None
    first = payload.geo_municipios[0]
    parts = first.split("::")
    if len(parts) >= 2 and parts[1]:
        return parts[1].zfill(3)
    return None


def _most_specific_activity(payload: DenueBusquedaPayload) -> str | None:
    codes = [str(value).strip() for value in (payload.actividad_codigos or []) if value and str(value).strip()]
    if not codes:
        return None
    return sorted(codes, key=lambda value: len(value), reverse=True)[0]


def _unique_preserve_order(values: list[str]) -> list[str]:
    return list(dict.fromkeys(values))


def _activity_codes_from_payload(payload: DenueBusquedaPayload) -> list[str]:
    codes = [str(value).strip() for value in (payload.actividad_codigos or []) if value and str(value).strip()]
    if not codes:
        return []
    return expand_denue_activity_codes(codes)


def _geo_targets_from_payload(payload: DenueBusquedaPayload) -> list[tuple[str | None, str | None]]:
    targets: list[tuple[str | None, str | None]] = []
    if payload.geo_municipios:
        for raw in payload.geo_municipios:
            parts = str(raw).split("::")
            estado = parts[0].zfill(2) if parts and parts[0] else None
            municipio = parts[1].zfill(3) if len(parts) >= 2 and parts[1] else None
            targets.append((estado, municipio))
    elif payload.geo_estados:
        for raw in payload.geo_estados:
            estado = str(raw).zfill(2) if raw is not None else None
            targets.append((estado, None))
    if not targets:
        targets.append((None, None))
    return targets
async def _build_advanced_meta(payload: DenueBusquedaPayload, repo: CRMRepository | None = None) -> dict[str, Any]:
    meta: dict[str, Any] = {"modo": payload.modo}
    if payload.texto_busqueda:
        meta["texto_busqueda"] = payload.texto_busqueda
    activity_codes = _activity_codes_from_payload(payload)
    if activity_codes:
        meta["actividad_codigos"] = activity_codes
        provided_names: list[str] = []
        if payload.actividad_nombres:
            provided_names = _unique_preserve_order(
                [str(value).strip() for value in payload.actividad_nombres if value and str(value).strip()]
            )
        if provided_names:
            meta["actividad_nombres"] = provided_names
        elif repo:
            names: list[str] = []
            try:
                titles = await repo.list_scian_clase_titles(codes=activity_codes)
            except CRMRepositoryError:
                titles = {}
            for code in activity_codes:
                title = titles.get(code)
                if isinstance(title, str) and title.strip():
                    names.append(title.strip())
                else:
                    names.append(code)
            if names:
                meta["actividad_nombres"] = names
    if payload.estrato_ids:
        meta["estrato_ids"] = payload.estrato_ids
    if payload.geo_estados:
        meta["geo_estados"] = payload.geo_estados
    if payload.geo_municipios:
        meta["geo_municipios"] = payload.geo_municipios
    return meta


