def _build_contact_log_entry(
    *,
    prospecto_id: Any,
    canal: str,
    estado: str,
    detalle: dict[str, Any] | None = None,
    error: str | None = None,
    batch_id: Any | None = None,
    envio_id: Any | None = None,
) -> dict[str, Any]:
    entry: dict[str, Any] = {
        "prospecto_id": str(prospecto_id),
        "canal": canal,
        "estado": estado,
        "detalle": detalle or {},
    }
    if error:
        entry["error"] = error
    if batch_id:
        entry["batch_id"] = str(batch_id)
    if envio_id:
        entry["envio_id"] = str(envio_id)
    return entry


def _rpc_field(data: Any, *keys: str) -> Any:
    row: Any
    if isinstance(data, list):
        row = data[0] if data else None
    else:
        row = data
    if isinstance(row, dict):
        for key in keys:
            if key in row:
                return row[key]
        if row:
            return next(iter(row.values()))
    if isinstance(row, (str, int, float)):
        return row
    if isinstance(data, dict):
        for key in keys:
            if key in data:
                return data[key]
        if data:
            return next(iter(data.values()))
    return None


def _is_jwt_expired_repo_error(exc: Exception) -> bool:
    message = str(exc).lower()
    return "jwt expired" in message or "pgrst303" in message


async def require_admin_user(
    *,
    repo: CRMRepository = Depends(get_repository),
    usuario_id: UUID | None = Depends(optional_usuario_id),
) -> UUID:
    if not usuario_id:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")
    has_role = await repo.user_has_role(usuario_id=usuario_id, role_code="admin")
    if not has_role:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")
    return usuario_id


def _normalize_reports_user_token(user_token: str | None) -> str | None:
    token = (user_token or "").strip()
    if not token:
        return None
    if _jwt_role(token) == "service_role":
        return None
    return token


_PERMISSION_EQUIVALENTS: dict[str, tuple[str, ...]] = {
    "ejecutar_busquedas": ("busquedas.run",),
    "busquedas.run": ("ejecutar_busquedas",),
}


async def _user_has_any_permission(
    repo: CRMRepository,
    *,
    organizacion_id: UUID,
    usuario_id: UUID,
    permission_codes: tuple[str, ...],
) -> bool:
    for code in permission_codes:
        if await repo.user_has_permission(
            organizacion_id=organizacion_id,
            usuario_id=usuario_id,
            codigo=code,
        ):
            return True
    return False


async def _current_user_has_any_permission(
    repo: CRMRepository,
    *,
    permission_codes: tuple[str, ...],
) -> bool:
    for code in permission_codes:
        if await repo.current_user_has_perm(codigo=code):
            return True
    return False


def require_permission(permission_code: str):
    normalized_code = permission_code.strip().lower()
    permission_codes = (normalized_code, *_PERMISSION_EQUIVALENTS.get(normalized_code, ()))

    async def _dependency(
        user_token: str | None = Depends(optional_user_token),
        usuario_id: UUID | None = Depends(optional_usuario_id),
        x_organizacion_id: Annotated[str | None, Header(alias="X-Organizacion-Id")] = None,
    ) -> str:
        if settings.environment.strip().lower() == "test" or _is_pytest_runtime():
            return user_token or "test-token"
        if not user_token:
            raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")
        if _jwt_role(user_token) == "service_role":
            if not usuario_id:
                raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")
            if not x_organizacion_id:
                raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")
            try:
                organizacion_id = UUID(x_organizacion_id)
            except ValueError as exc:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail="Encabezado X-Organizacion-Id inválido",
                ) from exc
            repo = CRMRepository()
            try:
                is_admin = await repo.user_has_role(usuario_id=usuario_id, role_code="admin")
                is_owner = await repo.user_has_role(usuario_id=usuario_id, role_code="owner")
                allowed = is_admin or is_owner or await _user_has_any_permission(
                    repo,
                    organizacion_id=organizacion_id,
                    usuario_id=usuario_id,
                    permission_codes=permission_codes,
                )
            except CRMRepositoryError as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc
            logger.info(
                "permission.check.service_role",
                extra={
                    "user_id": str(usuario_id),
                    "permission": normalized_code,
                    "permission_codes": permission_codes,
                    "allowed": allowed,
                    "ctx_es_admin": is_admin,
                    "ctx_es_owner": is_owner,
                    "organizacion_id": str(organizacion_id),
                },
            )
            if not allowed:
                raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")
            return user_token
        repo = CRMRepository(user_token=user_token)
        user_id = _jwt_verify_and_sub(user_token)
        try:
            permission_context = await repo.get_permission_context()
            es_admin = _coerce_bool(permission_context.get("es_admin")) is True
            es_owner = _coerce_bool(permission_context.get("es_owner")) is True
            allowed = es_admin or es_owner or await _current_user_has_any_permission(
                repo,
                permission_codes=permission_codes,
            )
        except CRMRepositoryError as exc:
            if _is_jwt_expired_repo_error(exc):
                raise HTTPException(
                    status_code=status.HTTP_401_UNAUTHORIZED,
                    detail="auth_required",
                ) from exc
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        logger.info(
            "permission.check",
            extra={
                "user_id": user_id,
                "permission": normalized_code,
                "permission_codes": permission_codes,
                "allowed": allowed,
                "ctx_es_admin": es_admin,
                "ctx_es_owner": es_owner,
            },
        )
        if not allowed:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")
        return user_token

    return _dependency


def require_any_permission(permission_codes: list[str]):
    async def _dependency(user_token: str = Depends(require_user_token)) -> str:
        if settings.environment.strip().lower() == "test" or _is_pytest_runtime():
            return user_token
        repo = CRMRepository(user_token=user_token)
        user_id = _jwt_verify_and_sub(user_token)
        try:
            permission_context = await repo.get_permission_context()
            es_admin = _coerce_bool(permission_context.get("es_admin")) is True
            es_owner = _coerce_bool(permission_context.get("es_owner")) is True
            allowed = es_admin or es_owner
            if not allowed:
                for code in permission_codes:
                    if await repo.current_user_has_perm(codigo=code):
                        allowed = True
                        break
        except CRMRepositoryError as exc:
            if _is_jwt_expired_repo_error(exc):
                raise HTTPException(
                    status_code=status.HTTP_401_UNAUTHORIZED,
                    detail="auth_required",
                ) from exc
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        logger.info(
            "permission.check.any",
            extra={
                "user_id": user_id,
                "permissions": permission_codes,
                "allowed": allowed,
                "ctx_es_admin": es_admin,
                "ctx_es_owner": es_owner,
            },
        )
        if not allowed:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")
        return user_token

    return _dependency


def require_owner_only():
    async def _dependency(user_token: str = Depends(require_user_token)) -> str:
        if settings.environment.strip().lower() == "test" or _is_pytest_runtime():
            return user_token
        repo = CRMRepository(user_token=user_token)
        try:
            permission_context = await repo.get_permission_context()
            es_owner = _coerce_bool(permission_context.get("es_owner")) is True
        except CRMRepositoryError as exc:
            if _is_jwt_expired_repo_error(exc):
                raise HTTPException(
                    status_code=status.HTTP_401_UNAUTHORIZED,
                    detail="auth_required",
                ) from exc
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not es_owner:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="owner_required")
        return user_token

    return _dependency


def require_owner_or_admin_for_master_tenant():
    async def _dependency(user_token: str = Depends(require_user_token)) -> str:
        if settings.environment.strip().lower() == "test" or _is_pytest_runtime():
            return user_token
        repo = CRMRepository(user_token=user_token)
        try:
            context = await repo.get_permission_context()
            es_admin = _coerce_bool(context.get("es_admin")) is True
            es_owner = _coerce_bool(context.get("es_owner")) is True
            org_raw = context.get("organizacion_id")
            org_id = UUID(str(org_raw)) if org_raw else None
        except CRMRepositoryError as exc:
            if _is_jwt_expired_repo_error(exc):
                raise HTTPException(
                    status_code=status.HTTP_401_UNAUTHORIZED,
                    detail="auth_required",
                ) from exc
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        except (TypeError, ValueError):
            org_id = None
            es_admin = False
            es_owner = False

        if not (es_owner or es_admin):
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="owner_or_admin_required")
        if org_id != GOOGLE_TRENDS_ALLOWED_ORGANIZACION_ID:
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="tenant_not_allowed")
        return user_token

    return _dependency


async def require_platform_admin(
    user_token: str = Depends(require_user_token),
) -> UUID:
    if settings.environment.strip().lower() == "test" or _is_pytest_runtime():
        user_id = _jwt_verify_and_sub(user_token)
        if user_id:
            try:
                return UUID(str(user_id))
            except (TypeError, ValueError):
                pass
        return UUID(int=0)
    try:
        repo = PlatformRepository()
    except PlatformRepositoryError as exc:
        raise HTTPException(status_code=500, detail=str(exc)) from exc

    try:
        user = await repo.auth_get_user(user_token=user_token)
    except PlatformRepositoryError as exc:
        raise HTTPException(status_code=401, detail=str(exc)) from exc
    raw_id = user.get("id")
    try:
        user_id = UUID(str(raw_id))
    except (TypeError, ValueError) as exc:
        raise HTTPException(status_code=401, detail="auth_user_invalid") from exc

    try:
        allowed = await repo.is_platform_admin(user_id=user_id)
    except PlatformRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not allowed:
        raise HTTPException(status_code=403, detail="platform_admin_required")
    return user_id


