@router.post("/catalog/item-details")
async def fetch_catalog_item_details(
    payload: CatalogItemDetailsRequest,
    _: str = Depends(require_permission("settings.view")),
    user_token: str = Depends(require_user_token),
) -> dict[str, Any]:
    try:
        organizacion_uuid = UUID(payload.organizacion_id)
    except ValueError:
        raise HTTPException(
            status.HTTP_400_BAD_REQUEST,
            detail="organizacion_id inválido.",
        )

    repo = CRMRepository(user_token=user_token)
    log_base = {
        "source": "api.fetch_catalog_item_details",
        "conversation_id": payload.conversacion_id,
        "organizacion_id": str(organizacion_uuid),
        "query": payload.query,
        "detail_level": payload.detail_level,
        "limit": payload.limit,
    }

    try:
        sql_items = await lookup_catalog_items_sql_first(
            repo,
            organizacion_id=organizacion_uuid,
            query=payload.query,
            limit=payload.limit,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "catalog.item_details_sql_lookup_failed",
            extra={"organizacion_id": payload.organizacion_id, "error": str(exc)},
        )
        sql_items = []

    if sql_items:
        matches_log: list[dict[str, Any]] = []
        items: list[dict[str, Any]] = []
        for item_data in sql_items[: payload.limit]:
            metadata_value = item_data.get("metadata") or item_data.get("metadatos")
            normalized_metadata = _normalize_metadata_value(metadata_value)
            metadata: Mapping[str, Any] | dict[str, Any]
            metadata = normalized_metadata or (
                metadata_value if isinstance(metadata_value, Mapping) else {}
            )
            if isinstance(metadata, Mapping):
                metadata = {str(key): val for key, val in metadata.items()}
            metadata_keys = list(metadata.keys()) if isinstance(metadata, Mapping) else []
            matches_log.append(
                {
                    "slug": item_data.get("slug"),
                    "similarity": None,
                    "metadata_keys": metadata_keys,
                    "metadata": metadata,
                    "fallback_used": True,
                    "strategy": "sql_direct",
                }
            )
            items.append(
                {
                    "nombre": item_data.get("nombre"),
                    "slug": item_data.get("slug"),
                    "tipo": item_data.get("tipo"),
                    "unidad": item_data.get("unidad"),
                    "precio_base": item_data.get("precio_base"),
                    "moneda": item_data.get("moneda"),
                    "activo": item_data.get("activo"),
                    "metadata": metadata,
                    "similarity": None,
                }
            )
        write_catalog_debug_entry(
            {
                **log_base,
                "match_count": len(items),
                "items_returned": len(items),
                "matches": matches_log,
                "strategy": "sql_first",
                "vector_used": False,
            }
        )
        return {
            "items": items,
            "detail_level": payload.detail_level,
            "source": "catalog_sql_direct",
        }

    service = CatalogEmbeddingService(repo)
    try:
        matches = await service.query_documents(
            organizacion_uuid,
            query=payload.query,
            limit=payload.limit,
            reason="fetch_catalog_item_details_fallback",
        )
    except CRMRepositoryError as exc:
        logger.exception(
            "catalog.item_details_search_failed",
            extra={"organizacion_id": payload.organizacion_id, "error": str(exc)},
        )
        raise HTTPException(
            status.HTTP_502_BAD_GATEWAY,
            detail="No se pudo consultar la vector store del catálogo.",
        ) from exc

    if not matches:
        write_catalog_debug_entry(
            {
                **log_base,
                "match_count": 0,
                "items_returned": 0,
                "matches": [],
                "error": "no_matches",
            }
        )
        raise HTTPException(
            status.HTTP_404_NOT_FOUND,
            detail="No se encontraron coincidencias para la consulta.",
        )

    matches_log: list[dict[str, Any]] = []
    items: list[dict[str, Any]] = []
    for match in matches:
        slug = match.metadata.get("slug")
        item_data: dict[str, Any] | None = None
        if isinstance(slug, str) and slug.strip():
            try:
                item_data = await repo.get_catalog_item_by_slug(
                    organizacion_id=organizacion_uuid,
                    slug=slug.strip(),
                )
            except CRMRepositoryError as exc:
                logger.warning(
                    "catalog.item_lookup_failed",
                    extra={
                        "organizacion_id": payload.organizacion_id,
                        "slug": slug,
                        "error": str(exc),
                    },
                )
        metadata_value = (
            item_data.get("metadata")
            if item_data and item_data.get("metadata")
            else item_data.get("metadatos")
            if item_data
            else None
        )
        content_metadata = _extract_metadata_from_content(match.contenido)
        normalized_metadata = _normalize_metadata_value(metadata_value)
        normalized_match = _normalize_metadata_value(match.metadata)
        merged_metadata: dict[str, Any] = {}
        if normalized_match:
            merged_metadata.update(normalized_match)
        if normalized_metadata:
            merged_metadata.update(normalized_metadata)
        if content_metadata:
            merged_metadata.update(content_metadata)
        metadata = merged_metadata or (
            metadata_value if isinstance(metadata_value, Mapping) else match.metadata
        )
        if isinstance(metadata, Mapping):
            metadata = {str(key): val for key, val in metadata.items()}
        metadata_keys = list(metadata.keys()) if isinstance(metadata, Mapping) else []
        matches_log.append(
            {
                "slug": slug,
                "similarity": match.similarity,
                "metadata_keys": metadata_keys,
                "metadata": metadata,
                "fallback_used": item_data is not None,
            }
        )
        items.append(
            {
                "nombre": item_data.get("nombre") if item_data else match.metadata.get("nombre"),
                "slug": item_data.get("slug") if item_data else match.metadata.get("slug"),
                "tipo": item_data.get("tipo") if item_data else match.metadata.get("tipo"),
                "unidad": item_data.get("unidad") if item_data else None,
                "precio_base": item_data.get("precio_base") if item_data else None,
                "moneda": item_data.get("moneda") if item_data else match.metadata.get("moneda"),
                "activo": item_data.get("activo") if item_data else match.metadata.get("activo"),
                "metadata": metadata,
                "similarity": match.similarity,
            }
        )

    write_catalog_debug_entry(
        {
            **log_base,
            "match_count": len(matches),
            "items_returned": len(items),
            "matches": matches_log,
        }
    )

    return {
        "items": items,
        "detail_level": payload.detail_level,
        "source": "vector_store_supabase",
    }


def _coerce_metadata(value: Any) -> dict[str, Any] | None:
    if isinstance(value, dict):
        parsed = value
    elif isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return None
        if not isinstance(parsed, dict):
            return None
    else:
        return None

    extra = parsed.get("extra")
    if isinstance(extra, str):
        try:
            parsed["extra"] = json.loads(extra)
        except json.JSONDecodeError:
            parsed["extra"] = None
    return parsed


def _parse_con_envio_canales_param(raw: str | None) -> list[str]:
    if not raw:
        return []
    parsed: list[str] = []
    seen: set[str] = set()
    for chunk in raw.split(","):
        value = (chunk or "").strip().lower()
        if value in {"correo", "whatsapp", "llamada"} and value not in seen:
            seen.add(value)
            parsed.append(value)
    return parsed


def _normalize_agenda_estado(value: Any) -> str:
    if isinstance(value, str):
        lowered = value.strip().lower()
    else:
        lowered = str(value).strip().lower() if value is not None else ""
    if not lowered:
        return "pendiente"
    if lowered in {"confirmed", "confirmada"}:
        return "confirmada"
    if lowered in {"cancelled", "cancelada"}:
        return "cancelada"
    if lowered in {"rescheduled", "reprogramada"}:
        return "reprogramada"
    if lowered in {"completed", "realizada"}:
        return "realizada"
    if lowered in {"pending", "pendiente"}:
        return "pendiente"
    return lowered


def _parse_iso_datetime(value: Any) -> datetime | None:
    if not value:
        return None
    try:
        raw = str(value).replace("Z", "+00:00")
        return datetime.fromisoformat(raw)
    except ValueError:
        return None


def _map_agenda_row(row: dict[str, Any]) -> dict[str, Any]:
    metadata_raw = row.get("metadata")
    metadata_parsed = _coerce_metadata(metadata_raw)
    if metadata_parsed is None and isinstance(metadata_raw, dict):
        metadata_parsed = metadata_raw
    metadata: dict[str, Any] = dict(metadata_parsed) if isinstance(metadata_parsed, dict) else {}
    estado = _normalize_agenda_estado(row.get("status") or metadata.get("estado"))
    oportunidad_id = (
        row.get("oportunidad_id") or metadata.get("oportunidad_id") or row.get("tarjeta_id")
    )

    contacto_payload = {
        "id": row.get("contacto_id") or row.get("contact_id"),
        "nombre": row.get("contacto_nombre") or "Contacto sin nombre",
        "correo": row.get("contacto_correo"),
        "telefono": row.get("contacto_telefono"),
        "empresa": row.get("contacto_empresa"),
        "origen": row.get("contacto_origen"),
    }
    asignado_payload: dict[str, Any] | None = None
    if row.get("asignado_a_usuario_id") or row.get("asignado_nombre"):
        asignado_payload = {
            "id": row.get("asignado_a_usuario_id"),
            "nombre": row.get("asignado_nombre"),
        }
    propietario_payload: dict[str, Any] | None = None
    if row.get("propietario_usuario_id") or row.get("propietario_nombre"):
        propietario_payload = {
            "id": row.get("propietario_usuario_id"),
            "nombre": row.get("propietario_nombre"),
        }

    return {
        "id": row.get("id"),
        "resource_id": row.get("resource_id"),
        "hold_id": row.get("hold_id"),
        "oportunidad_id": oportunidad_id,
        "tarjeta_id": row.get("tarjeta_id"),
        "contacto_id": contacto_payload["id"],
        "conversacion_id": row.get("conversacion_id"),
        "start_at": row.get("start_at"),
        "end_at": row.get("end_at"),
        "timezone": row.get("timezone"),
        "estado": estado,
        "notes": row.get("notes"),
        "meeting_url": row.get("meeting_url"),
        "external_join_url": row.get("external_join_url"),
        "canal": row.get("tarjeta_canal") or row.get("conversacion_canal"),
        "provider": "calendar",
        "lead_score": row.get("tarjeta_lead_score"),
        "etapa_nombre": row.get("etapa_nombre"),
        "metadata": metadata,
        "contacto": contacto_payload,
        "asignado": asignado_payload,
        "propietario": propietario_payload,
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def _normalize_calendar_exception_kind(value: str | None) -> str:
    normalized = (value or "").strip().lower()
    if normalized not in {"block", "extra"}:
        raise HTTPException(status_code=400, detail="kind_invalid")
    return normalized


