@router.get("/oportunidades/ventas/lista", response_model=list[CRMSaleReadyOpportunity])
async def list_sale_ready_opportunities(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    user_token: str = Depends(require_user_token),  # noqa: ARG001
    limit: Annotated[int, Query(ge=1, le=200)] = 100,
    contacto_captura_estado: str | None = Query(default=None),
) -> list[CRMSaleReadyOpportunity]:
    try:
        rows = await repo.list_sale_ready_opportunities(
            organizacion_id=organizacion_id,
            limit=limit,
            contacto_captura_estado=contacto_captura_estado,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    allowed: list[CRMSaleReadyOpportunity] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        stage = row.get("etapa") or {}
        code = stage.get("codigo")
        contacto = row.get("contacto") or {}
        cuenta = row.get("cuenta") or {}
        allowed.append(
            CRMSaleReadyOpportunity(
                id=_safe_uuid(row.get("id")),
                titulo=row.get("titulo") or "",
                estado=row.get("estado") or "",
                monto_estimado=_coerce_optional_number(row.get("monto_estimado")),
                moneda=row.get("moneda"),
                descripcion=row.get("descripcion"),
                probabilidad=_coerce_optional_number(row.get("probabilidad")),
                etapa_codigo=code,
                etapa_nombre=stage.get("nombre"),
                etapa_categoria=stage.get("categoria"),
                cuenta_id=_safe_uuid(cuenta.get("id")),
                cuenta_nombre=cuenta.get("nombre"),
                contacto_id=_safe_uuid(contacto.get("id")),
                contacto_nombre=contacto.get("nombre_completo") or contacto.get("nombres") or None,
                contacto_correo=contacto.get("correo"),
                contacto_telefono=contacto.get("telefono_e164"),
                metadata=row.get("metadata"),
            )
        )
    return allowed


@router.post(
    "/oportunidades",
    response_model=CRMOpportunity,
    status_code=status.HTTP_201_CREATED,
)
async def create_opportunity(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    payload: CRMOpportunityCreate,
) -> CRMOpportunity:
    body = payload.model_dump(mode="json", exclude_unset=True)
    try:
        row = await repo.create_opportunity(
            organizacion_id=organizacion_id,
            payload=body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    # Registrar historial de etapa inicial (best-effort)
    if payload.etapa_id:
        history_payload: dict[str, str] = {
            "oportunidad_id": str(row["id"]),
            "etapa_destino_id": str(payload.etapa_id),
            "fuente": "api",
        }
        if usuario_id:
            history_payload["cambiado_por_usuario_id"] = str(usuario_id)
        try:
            await repo.append_stage_history(
                organizacion_id=organizacion_id,
                payload=history_payload,
            )
        except CRMRepositoryError as exc:  # pragma: no cover - no debe frenar creación
            logger.warning("crm.historial_no_registrado", extra={"error": str(exc)})

    return CRMOpportunity.model_validate(row)


