def _normalize_column_value(value: str | None) -> str:
    if not value:
        return ""
    normalized = unicodedata.normalize("NFKD", value)
    filtered = "".join(ch for ch in normalized if not unicodedata.combining(ch))
    return re.sub(r"\s+", " ", filtered).strip().lower()


def _slugify(value: str) -> str:
    text = unicodedata.normalize("NFKD", value or "")
    slug = "".join(ch if ch.isalnum() else "-" for ch in text.lower())
    slug = re.sub(r"-+", "-", slug).strip("-")
    return slug or ""


def _parse_metadata_value(raw_value: str | None, field_type: str) -> str | float | bool | None:
    if not raw_value:
        return None
    cleaned = raw_value.strip()
    if not cleaned:
        return None
    lowered = cleaned.lower()
    if field_type == "boolean":
        if lowered in {"1", "si", "sí", "true", "t", "yes", "y"}:
            return True
        if lowered in {"0", "no", "false", "f", "n"}:
            return False
        return None
    if field_type == "number":
        normalized = cleaned.replace(",", ".")
        try:
            return float(normalized)
        except ValueError:
            return None
    return cleaned


def _normalize_scheme_fields(raw_fields: Any) -> list[dict[str, Any]]:
    fields: list[dict[str, Any]] = []
    if not isinstance(raw_fields, list):
        return fields
    for raw in raw_fields:
        if not isinstance(raw, dict):
            continue
        field_id = str(raw.get("id") or raw.get("slug") or "").strip()
        if not field_id:
            continue
        field_type = str(raw.get("type") or "text").strip().lower()
        if field_type not in {"text", "number", "boolean", "select"}:
            field_type = "text"
        label = str(raw.get("label") or raw.get("name") or field_id).strip()
        fields.append(
            {
                "id": field_id,
                "label": label,
                "type": field_type,
                "required": bool(raw.get("required")),
            }
        )
    return fields


def _build_field_header_map(
    headers: list[str], fields: list[dict[str, Any]]
) -> dict[str, str]:
    normalized_headers = set(headers)
    mapping: dict[str, str] = {}
    for field in fields:
        for candidate in filter(None, [field.get("id"), field.get("label")]):
            normalized_candidate = _normalize_column_value(str(candidate))
            if normalized_candidate in normalized_headers:
                mapping[field["id"]] = normalized_candidate
                break
    return mapping


BASE_HEADER_CANDIDATES = {
    "nombre": ["nombre", "name"],
    "linea": ["linea", "línea", "line", "linea_nombre", "línea_nombre"],
    "familia": ["familia", "family", "familia_nombre"],
    "modelo": ["modelo", "model", "modelo_nombre"],
    "slug": ["slug"],
}

BASE_HEADER_KEYS = {
    _normalize_column_value(candidate)
    for values in BASE_HEADER_CANDIDATES.values()
    for candidate in values
    if candidate
}


def _pick_value(row: Mapping[str, str], candidates: list[str]) -> str | None:
    for candidate in candidates:
        normalized = _normalize_column_value(candidate)
        if not normalized:
            continue
        value = row.get(normalized)
        if value:
            return value
    return None


async def _read_import_rows(
    file: UploadFile,
) -> tuple[dict[str, str], list[dict[str, str]]]:
    content = await file.read()
    filename = file.filename or ""
    suffix = Path(filename).suffix.lower()
    headers_map: dict[str, str] = {}
    rows: list[dict[str, str]] = []
    if suffix in {".xlsx", ".xls"}:
        if load_workbook is None:
            raise RuntimeError("openpyxl_required")
        workbook = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
        try:
            sheet = workbook.active
            iterator = sheet.iter_rows(values_only=True)
            header_row = next(iterator, None)
            if not header_row:
                return headers_map, []
            normalized_headers: list[str] = []
            for header in header_row:
                normalized = _normalize_column_value(str(header or ""))
                if not normalized:
                    continue
                normalized_headers.append(normalized)
                headers_map.setdefault(normalized, str(header or ""))
            for row in iterator:
                row_map: dict[str, str] = {}
                for idx, header in enumerate(normalized_headers):
                    cell_value = row[idx] if idx < len(row) else None
                    row_map[header] = str(cell_value).strip() if cell_value is not None else ""
                if any(value for value in row_map.values()):
                    rows.append(row_map)
        finally:
            workbook.close()
    else:
        text = content.decode("utf-8-sig", errors="replace")
        reader = csv.DictReader(io.StringIO(text))
        fieldnames = reader.fieldnames or []
        normalized_headers: list[str] = []
        for header in fieldnames:
            normalized = _normalize_column_value(header)
            if not normalized:
                continue
            normalized_headers.append(normalized)
            headers_map.setdefault(normalized, header or "")
        for raw_row in reader:
            row_map: dict[str, str] = {}
            for header, normalized in zip(fieldnames, normalized_headers):
                raw_value = raw_row.get(header, "")
                row_map[normalized] = (raw_value or "").strip()
            if any(value for value in row_map.values()):
                rows.append(row_map)
    return headers_map, rows


def _build_error_payload(row: Mapping[str, str], headers_map: dict[str, str]) -> dict[str, str]:
    return {
        headers_map.get(key, key): value
        for key, value in row.items()
        if value
    }


@router.get("/contacts/search", response_model=CRMContactSearchResponse)
async def search_contacts(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.read")),
    query: Annotated[str, Query(min_length=2, alias="q")],
    limit: Annotated[int, Query(ge=1, le=25)] = 8,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> CRMContactSearchResponse:
    rows = await repo.search_contacts(
        organizacion_id=organizacion_id,
        query=query,
        limit=limit,
        offset=offset,
    )
    items: list[CRMContactSearchItem] = []
    for row in rows:
        contacto_id = _safe_uuid(row.get("id"))
        if not contacto_id:
            continue
        items.append(
            CRMContactSearchItem(
                id=contacto_id,
                nombre=row.get("nombre_completo"),
                correo=row.get("correo"),
                telefono=row.get("telefono_e164"),
                empresa=row.get("company_name"),
            )
        )
    return CRMContactSearchResponse(items=items, limit=limit, offset=offset)


@router.post("/personas/alta/validar", response_model=CRMPersonaAltaValidationResponse)
async def validate_persona_alta(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    payload: CRMPersonaAltaRequest,
) -> CRMPersonaAltaValidationResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    dedupe = payload.dedupe

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal) and not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="medio_contacto_required")

    persona_candidates, account_candidates, suggested_persona_id, suggested_account_id, requires_confirmation = (
        await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
        )
    )

    return CRMPersonaAltaValidationResponse(
        requiere_confirmacion=requires_confirmation,
        candidatos_persona=persona_candidates,
        candidatos_cuenta=account_candidates,
        sugerencia_persona_reutilizar_id=suggested_persona_id,
        sugerencia_cuenta_reutilizar_id=suggested_account_id,
    )


@router.post("/personas/alta", response_model=CRMPersonaAltaResponse, status_code=status.HTTP_201_CREATED)
async def create_persona_alta(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    payload: CRMPersonaAltaRequest,
) -> CRMPersonaAltaResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    relacion = payload.relacion
    extras = _persona_alta_normalize_extras(payload.extras)
    dedupe = payload.dedupe
    dedupe = payload.dedupe

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal) and not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="medio_contacto_required")

    existing_account: CRMAccount | None = None
    persona_candidates: list[dict[str, Any]] = []
    account_candidates: list[dict[str, Any]] = []
    reused_account_id: UUID | None = None
    dedupe_contacto_id: UUID | None = dedupe.persona_reutilizar_id if dedupe else None

    if dedupe and dedupe.cuenta_reutilizar_id and cuenta:
        cuenta = cuenta.model_copy(update={"cuenta_id": dedupe.cuenta_reutilizar_id})

    try:
        (
            persona_candidates,
            account_candidates,
            suggested_persona_id,
            suggested_account_id,
            requires_confirmation,
        ) = await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    force_create_new = bool(dedupe and dedupe.confirmar_creacion)
    if force_create_new:
        suggested_persona_id = None
        suggested_account_id = None
        dedupe_contacto_id = None

    if requires_confirmation:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "dedupe_confirmation_required",
                "message": "Se detectaron posibles duplicados. Confirma si deseas reutilizar o crear uno nuevo.",
                "candidatos_persona": persona_candidates,
                "candidatos_cuenta": account_candidates,
                "sugerencia_persona_reutilizar_id": str(suggested_persona_id) if suggested_persona_id else None,
                "sugerencia_cuenta_reutilizar_id": str(suggested_account_id) if suggested_account_id else None,
            },
        )

    if not dedupe_contacto_id and not force_create_new:
        dedupe_contacto_id = suggested_persona_id

    if contexto.modo == "empresa_existente":
        if not cuenta or not cuenta.cuenta_id:
            raise HTTPException(status_code=400, detail="cuenta_id_required")
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
    elif cuenta and cuenta.cuenta_id:
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
        reused_account_id = existing_account.id
    elif suggested_account_id and cuenta and not force_create_new:
        cuenta = cuenta.model_copy(update={"cuenta_id": suggested_account_id})
        reused_account_id = suggested_account_id
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=suggested_account_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            existing_account = CRMAccount.model_validate(account_row)

    contact_payload = _persona_alta_to_contact_payload(
        persona=persona,
        contexto=contexto,
        cuenta=cuenta,
        extras=extras,
        existing_account=existing_account,
    )

    try:
        if dedupe_contacto_id:
            contact_row = await repo.update_contact(
                organizacion_id=organizacion_id,
                contacto_id=dedupe_contacto_id,
                payload={key: value for key, value in contact_payload.items() if value is not None},
            )
        else:
            contact_row = await repo.create_contact(
                organizacion_id=organizacion_id,
                payload={key: value for key, value in contact_payload.items() if value is not None},
            )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    try:
        persona_out = CRMContact.model_validate(contact_row)
    except ValidationError as exc:
        logger.exception(
            "crm.persona_update.persona_validation_failed",
            extra={
                "contacto_id": str(contacto_id),
                "errors": exc.errors(),
            },
        )
        raise HTTPException(status_code=502, detail="persona_response_invalid") from exc
    account_out: CRMAccount | None = None
    relation_out: CRMCuentaPersonaRelacion | None = None

    if persona_out.cuenta_id:
        if cuenta:
            account_patch = {
                key: value
                for key, value in _persona_alta_to_account_payload(
                    persona=persona,
                    contexto=contexto,
                    cuenta=cuenta,
                    extras=extras,
                    existing_account=existing_account,
                ).items()
                if value not in (None, "", {}, [])
            }
            if account_patch:
                try:
                    await repo.update_account(
                        organizacion_id=organizacion_id,
                        account_id=persona_out.cuenta_id,
                        payload=account_patch,
                    )
                except CRMRepositoryError as exc:
                    raise HTTPException(status_code=502, detail=str(exc)) from exc

        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=persona_out.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            try:
                account_out = CRMAccount.model_validate(account_row)
            except ValidationError as exc:
                logger.exception(
                    "crm.persona_update.account_validation_failed",
                    extra={
                        "contacto_id": str(contacto_id),
                        "cuenta_id": str(persona_out.cuenta_id),
                        "errors": exc.errors(),
                    },
                )
                raise HTTPException(status_code=502, detail="account_response_invalid") from exc

        relation_defaults = {
            "rol_en_cuenta": (
                relacion.rol_en_cuenta
                if relacion and _persona_alta_clean_text(relacion.rol_en_cuenta)
                else ("dueno" if contexto.modo == "persona_fisica_actividad_empresarial" else "contacto_principal")
            ),
            "puesto": relacion.puesto if relacion else persona.puesto,
            "es_contacto_principal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_contacto_principal if relacion else True),
            "es_contacto_facturacion": relacion.es_contacto_facturacion if relacion else False,
            "es_representante_legal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_representante_legal if relacion else False),
            "activo": relacion.activo if relacion else True,
            "fecha_inicio": relacion.fecha_inicio.isoformat() if relacion and relacion.fecha_inicio else None,
            "fecha_fin": relacion.fecha_fin.isoformat() if relacion and relacion.fecha_fin else None,
            "notas": relacion.notas if relacion else None,
            "metadata": (
                {**relacion.metadata, "contexto_modo": contexto.modo}
                if relacion and relacion.metadata
                else {"contexto_modo": contexto.modo}
            ),
        }
        try:
            relation_row = await repo.upsert_contact_account_relation(
                organizacion_id=organizacion_id,
                contacto_id=persona_out.id,
                cuenta_id=persona_out.cuenta_id,
                payload=relation_defaults,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        try:
            relation_out = CRMCuentaPersonaRelacion.model_validate(relation_row)
        except ValidationError as exc:
            logger.exception(
                "crm.persona_update.relation_validation_failed",
                extra={
                    "contacto_id": str(contacto_id),
                    "cuenta_id": str(persona_out.cuenta_id),
                    "errors": exc.errors(),
                },
            )
            raise HTTPException(status_code=502, detail="relation_response_invalid") from exc

    return CRMPersonaAltaResponse(
        persona=persona_out,
        cuenta=account_out,
        relacion=relation_out,
        resumen={
            "modo": contexto.modo,
            "persona_id": str(persona_out.id),
            "cuenta_id": str(persona_out.cuenta_id) if persona_out.cuenta_id else None,
            "deduplicado": bool(dedupe_contacto_id),
            "contacto_reutilizado_id": str(dedupe_contacto_id) if dedupe_contacto_id else None,
            "cuenta_reutilizada_id": str(reused_account_id) if reused_account_id else None,
            "candidatos_persona": persona_candidates,
            "candidatos_cuenta": account_candidates,
        },
    )


@router.patch("/personas/{contacto_id}", response_model=CRMPersonaAltaResponse)
async def update_persona(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    contacto_id: UUID,
    payload: CRMPersonaEditRequest,
) -> CRMPersonaAltaResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    relacion = payload.relacion
    extras = _persona_alta_normalize_extras(payload.extras)
    dedupe = payload.dedupe

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal) and not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="medio_contacto_required")

    existing_account: CRMAccount | None = None
    persona_candidates: list[dict[str, Any]] = []
    account_candidates: list[dict[str, Any]] = []
    reused_account_id: UUID | None = None
    dedupe_contacto_id: UUID | None = dedupe.persona_reutilizar_id if dedupe else None

    if dedupe and dedupe.cuenta_reutilizar_id and cuenta:
        cuenta = cuenta.model_copy(update={"cuenta_id": dedupe.cuenta_reutilizar_id})

    exclude_account_id = cuenta.cuenta_id if cuenta and cuenta.cuenta_id else None
    try:
        (
            persona_candidates,
            account_candidates,
            suggested_persona_id,
            suggested_account_id,
            requires_confirmation,
        ) = await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
            exclude_contacto_id=contacto_id,
            exclude_account_id=exclude_account_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    force_create_new = bool(dedupe and dedupe.confirmar_creacion)
    if force_create_new:
        suggested_persona_id = None
        suggested_account_id = None
        dedupe_contacto_id = None

    if requires_confirmation:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "dedupe_confirmation_required",
                "message": "Se detectaron posibles duplicados. Confirma si deseas reutilizar o crear uno nuevo.",
                "candidatos_persona": persona_candidates,
                "candidatos_cuenta": account_candidates,
                "sugerencia_persona_reutilizar_id": str(suggested_persona_id) if suggested_persona_id else None,
                "sugerencia_cuenta_reutilizar_id": str(suggested_account_id) if suggested_account_id else None,
            },
        )

    if not dedupe_contacto_id and not force_create_new:
        dedupe_contacto_id = suggested_persona_id

    if contexto.modo == "empresa_existente":
        if not cuenta or not cuenta.cuenta_id:
            raise HTTPException(status_code=400, detail="cuenta_id_required")
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
    elif cuenta and cuenta.cuenta_id:
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=cuenta.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not account_row:
            raise HTTPException(status_code=404, detail="cuenta_no_encontrada")
        existing_account = CRMAccount.model_validate(account_row)
        reused_account_id = existing_account.id
    elif suggested_account_id and cuenta and not force_create_new:
        cuenta = cuenta.model_copy(update={"cuenta_id": suggested_account_id})
        reused_account_id = suggested_account_id
        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=suggested_account_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            existing_account = CRMAccount.model_validate(account_row)

    contact_payload = _persona_alta_to_contact_payload(
        persona=persona,
        contexto=contexto,
        cuenta=cuenta,
        extras=extras,
        existing_account=existing_account,
    )
    if contexto.modo == "solo_persona":
        contact_payload["cuenta_id"] = None
        contact_payload["company_name"] = None

    try:
        contact_row = await repo.update_contact(
            organizacion_id=organizacion_id,
            contacto_id=contacto_id,
            payload={key: value for key, value in contact_payload.items() if value is not None},
        )
    except CRMRepositoryError as exc:
        if "contacto_no_encontrado" in str(exc):
            raise HTTPException(status_code=404, detail="contacto_no_encontrado") from exc
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    persona_out = CRMContact.model_validate(contact_row)
    account_out: CRMAccount | None = None
    relation_out: CRMCuentaPersonaRelacion | None = None

    if persona_out.cuenta_id:
        # Si la UI mandó datos de cuenta, los aplicamos también sobre cuentas existentes.
        if cuenta:
            account_patch = {
                key: value
                for key, value in _persona_alta_to_account_payload(
                    persona=persona,
                    contexto=contexto,
                    cuenta=cuenta,
                    extras=extras,
                    existing_account=existing_account,
                ).items()
                if value not in (None, "", {}, [])
            }
            if account_patch:
                try:
                    await repo.update_account(
                        organizacion_id=organizacion_id,
                        account_id=persona_out.cuenta_id,
                        payload=account_patch,
                    )
                except CRMRepositoryError as exc:
                    raise HTTPException(status_code=502, detail=str(exc)) from exc

        try:
            account_row = await repo.get_account(organizacion_id=organizacion_id, account_id=persona_out.cuenta_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if account_row:
            account_out = CRMAccount.model_validate(account_row)

        relation_defaults = {
            "rol_en_cuenta": (
                relacion.rol_en_cuenta
                if relacion and _persona_alta_clean_text(relacion.rol_en_cuenta)
                else ("dueno" if contexto.modo == "persona_fisica_actividad_empresarial" else "contacto_principal")
            ),
            "puesto": relacion.puesto if relacion else persona.puesto,
            "es_contacto_principal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_contacto_principal if relacion else True),
            "es_contacto_facturacion": relacion.es_contacto_facturacion if relacion else False,
            "es_representante_legal": True if contexto.modo == "persona_fisica_actividad_empresarial" else (relacion.es_representante_legal if relacion else False),
            "activo": relacion.activo if relacion else True,
            "fecha_inicio": relacion.fecha_inicio.isoformat() if relacion and relacion.fecha_inicio else None,
            "fecha_fin": relacion.fecha_fin.isoformat() if relacion and relacion.fecha_fin else None,
            "notas": relacion.notas if relacion else None,
            "metadata": (
                {**relacion.metadata, "contexto_modo": contexto.modo}
                if relacion and relacion.metadata
                else {"contexto_modo": contexto.modo}
            ),
        }
        try:
            relation_row = await repo.upsert_contact_account_relation(
                organizacion_id=organizacion_id,
                contacto_id=contacto_id,
                cuenta_id=persona_out.cuenta_id,
                payload=relation_defaults,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        relation_out = CRMCuentaPersonaRelacion.model_validate(relation_row)

    return CRMPersonaAltaResponse(
        persona=persona_out,
        cuenta=account_out,
        relacion=relation_out,
        resumen={
            "modo": contexto.modo,
            "persona_id": str(persona_out.id),
            "cuenta_id": str(persona_out.cuenta_id) if persona_out.cuenta_id else None,
            "deduplicado": bool(dedupe_contacto_id),
            "contacto_reutilizado_id": str(dedupe_contacto_id) if dedupe_contacto_id else None,
            "cuenta_reutilizada_id": str(reused_account_id) if reused_account_id else None,
            "candidatos_persona": persona_candidates,
            "candidatos_cuenta": account_candidates,
        },
    )


@router.post("/personas/{contacto_id}/validar", response_model=CRMPersonaAltaValidationResponse)
async def validate_persona_update(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("contacts.write")),
    contacto_id: UUID,
    payload: CRMPersonaEditRequest,
) -> CRMPersonaAltaValidationResponse:
    persona = _persona_alta_normalize_persona(payload.persona)
    contexto = payload.contexto_comercial
    cuenta = _persona_alta_normalize_cuenta(payload.cuenta)
    dedupe = payload.dedupe

    if not _persona_alta_clean_text(persona.nombre) or not _persona_alta_clean_text(persona.apellido_paterno):
        raise HTTPException(status_code=400, detail="persona_incompleta")
    if not _persona_alta_clean_text(persona.correo_principal) and not _persona_alta_clean_text(persona.telefono_principal_e164):
        raise HTTPException(status_code=400, detail="medio_contacto_required")

    exclude_account_id = cuenta.cuenta_id if cuenta and cuenta.cuenta_id else None
    persona_candidates, account_candidates, suggested_persona_id, suggested_account_id, requires_confirmation = (
        await _persona_alta_build_dedupe_preview(
            repo=repo,
            organizacion_id=organizacion_id,
            contexto=contexto,
            persona=persona,
            cuenta=cuenta,
            dedupe=dedupe,
            exclude_contacto_id=contacto_id,
            exclude_account_id=exclude_account_id,
        )
    )

    return CRMPersonaAltaValidationResponse(
        requiere_confirmacion=requires_confirmation,
        candidatos_persona=persona_candidates,
        candidatos_cuenta=account_candidates,
        sugerencia_persona_reutilizar_id=suggested_persona_id,
        sugerencia_cuenta_reutilizar_id=suggested_account_id,
    )


