@router.put("/prospeccion/prospectos/views")
async def guardar_vistas_prospectos(
    *,
    payload: ProspectosSavedViewsPayload,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
) -> dict[str, Any]:
    """Reemplaza la colección de vistas guardadas por usuario para prospectos."""

    views: list[dict[str, Any]] = []
    for item in payload.views[:PROSPECTOS_PREFS_VIEWS_MAX]:
        view_id = item.id or str(uuid4())
        state = item.state if isinstance(item.state, dict) else {}
        views.append(
            {
                "id": view_id,
                "name": item.name,
                "state": state,
            }
        )
    value = {"views": views}
    try:
        await repo.upsert_prospeccion_user_preference(
            usuario_token=user_token,
            modulo=PROSPECTOS_PREFS_MODULO,
            clave=PROSPECTOS_PREFS_CLAVE_VIEWS,
            valor=value,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {"ok": True, "views": views}


@router.get("/prospeccion/prospectos/contact-indicadores")
async def listar_prospecto_contact_indicadores(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    prospecto_ids: Annotated[list[UUID] | None, Query(alias="prospecto_id")] = None,
) -> dict[str, Any]:
    """Devuelve los indicadores agregados de contacto por prospecto."""

    if not prospecto_ids:
        raise HTTPException(status_code=400, detail="prospecto_ids_required")
    normalized_ids = sorted(set(prospecto_ids), key=str)
    if len(normalized_ids) > 50:
        raise HTTPException(status_code=400, detail="prospecto_ids_limit_exceeded")
    cache_key = _build_contact_indicators_cache_key(
        {
            "user": user_token,
            "prospecto_ids": [str(value) for value in normalized_ids],
        }
    )
    cached_rows = await _read_contact_indicators_cache(cache_key)
    if cached_rows is not None:
        logger.info(
            "crm.prospectos.contact_indicadores.cache_hit",
            extra={"rows": len(cached_rows), "requested_ids": len(normalized_ids)},
        )
        return {"ok": True, "items": cached_rows}
    try:
        rows = await _retry_transient_repo_error(
            operation="list_prospecto_contact_indicators",
            func=lambda: repo.list_prospecto_contact_indicators(
                usuario_token=user_token,
                prospecto_ids=normalized_ids,
            ),
            retries=1,
        )
    except CRMRepositoryError as exc:
        if _is_transient_supabase_error(exc):
            logger.warning(
                "crm.prospectos.contact_indicadores.degraded_empty",
                extra={
                    "requested_ids": len(normalized_ids),
                    "error": str(exc),
                },
            )
            return {"ok": True, "items": [], "degraded": True}
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    serializable_rows = _normalize_total_envios_without_cancelled(
        [row for row in rows if isinstance(row, dict)]
    )
    await _write_contact_indicators_cache(cache_key, serializable_rows)
    return {"ok": True, "items": serializable_rows}


