@router.get("/prospeccion/campanas")
async def prospeccion_campanas_dashboard(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    params: ProspeccionCampanaQuery = Depends(),
) -> dict[str, Any]:
    """Dashboard compacto de campañas (agrupa lotes por campana)."""

    limit = params.limit
    try:
        batches, _ = await repo.list_contact_batches(
            usuario_token=user_token,
            limit=limit,
            offset=0,
            order="creado_en.desc",
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    batch_ids: list[UUID] = []
    for row in batches:
        batch_id = row.get("id")
        try:
            if batch_id:
                batch_ids.append(UUID(str(batch_id)))
        except (ValueError, TypeError):
            continue

    try:
        resumenes = await repo.summarize_envios_por_batches(
            usuario_token=user_token,
            batch_ids=batch_ids,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    campana_ids: set[str] = set()
    for row in batches:
        campana_id = row.get("campana_id")
        if campana_id:
            campana_ids.add(str(campana_id))

    campana_map: dict[str, dict[str, Any]] = {}
    if campana_ids:
        try:
            campanas = await repo.list_campaigns(organizacion_id=organizacion_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        for campana in campanas:
            campana_id = str(campana.get("id"))
            metadata = _ensure_dict(campana.get("metadata"), default={})
            if str(metadata.get("deleted")).lower() in {"true", "1", "yes"}:
                continue
            if campana_id in campana_ids:
                campana_map[campana_id] = campana

    grouped: dict[str, dict[str, Any]] = {}
    for row in batches:
        batch_id = str(row.get("id"))
        if not batch_id:
            continue
        campana_id_raw = row.get("campana_id")
        campana_key = str(campana_id_raw) if campana_id_raw else "sin_campana"
        campana_info = campana_map.get(str(campana_id_raw)) if campana_id_raw else None
        campana_nombre = campana_info.get("nombre") if campana_info else None
        batch_totales = resumenes.get(batch_id, {})
        batch_item = {
            "id": batch_id,
            "campana_id": str(campana_id_raw) if campana_id_raw else None,
            "campana_nombre": campana_nombre or row.get("titulo") or ("Sin campaña" if not campana_id_raw else None),
            "titulo": row.get("titulo"),
            "estado": row.get("estado"),
            "total_prospectos": row.get("total_prospectos"),
            "canales": row.get("canales") or [],
            "programacion": row.get("programacion") or {},
            "filtros": row.get("filtros") or {},
            "metadata": row.get("metadata") or {},
            "lista_id": row.get("lista_id"),
            "creado_en": row.get("creado_en"),
            "totales": batch_totales,
        }
        group = grouped.setdefault(
            campana_key,
            {
                "campana_id": batch_item["campana_id"],
                "campana_nombre": campana_nombre or ("Sin campaña" if campana_key == "sin_campana" else None),
                "batches": [],
                "totales": {},
            },
        )
        group["batches"].append(batch_item)
        for estado, count in batch_totales.items():
            group["totales"][estado] = group["totales"].get(estado, 0) + count

    return {"ok": True, "items": list(grouped.values())}


@router.get("/prospeccion/campanas/atribucion")
async def prospeccion_campanas_atribucion(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    params: ProspeccionCampanaAtribucionQuery = Depends(),
) -> dict[str, Any]:
    """Resumen persistente de desempeño por campaña/plantilla."""
    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    date_from_dt, date_to_exclusive = local_date_range_to_utc(
        date_from=params.date_from,
        date_to=params.date_to,
        timezone_name=effective_timezone,
    )
    date_to_dt = (
        (date_to_exclusive - timedelta(microseconds=1)) if date_to_exclusive is not None else None
    )
    if date_from_dt and date_to_dt and date_from_dt > date_to_dt:
        raise HTTPException(status_code=400, detail="metricas_date_range_invalid")

    rows: list[dict[str, Any]] = []
    try:
        page_size = max(1, min(params.limit, 1000))
        page_offset = 0
        while True:
            page_rows = await repo.get_prospeccion_campana_template_atribucion_rango(
                usuario_token=user_token,
                organizacion_id=organizacion_id,
                campana_id=params.campana_id,
                date_from_iso=date_from_dt.isoformat() if date_from_dt else None,
                date_to_iso=date_to_dt.isoformat() if date_to_dt else None,
                limit=page_size,
                offset=page_offset,
            )
            if not page_rows:
                break
            rows.extend(page_rows)
            if len(page_rows) < page_size:
                break
            page_offset += len(page_rows)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    items: list[dict[str, Any]] = []
    for row in rows:
        items.append(
            {
                "campana_id": row.get("campana_id"),
                "campana_nombre": row.get("campana_nombre"),
                "canal": row.get("canal"),
                "template_id": row.get("template_id"),
                "template_slug": row.get("template_slug"),
                "template_nombre": row.get("template_nombre"),
                "twilio_content_sid": row.get("twilio_content_sid"),
                "envios_totales": int(row.get("envios_totales") or 0),
                "envios_enviados": int(row.get("envios_enviados") or 0),
                "envios_entregados": int(row.get("envios_entregados") or 0),
                "envios_fallidos": int(row.get("envios_fallidos") or 0),
                "envios_omitidos": int(row.get("envios_omitidos") or 0),
                "envios_respondidos": int(row.get("envios_respondidos") or 0),
                "brevo_aperturas": int(row.get("brevo_aperturas") or 0),
                "brevo_clicks": int(row.get("brevo_clicks") or 0),
                "sesiones_utm": int(row.get("sesiones_utm") or 0),
                "tasa_entrega_pct": float(row.get("tasa_entrega_pct") or 0),
                "tasa_respuesta_pct": float(row.get("tasa_respuesta_pct") or 0),
                "click_to_session_pct": float(row.get("click_to_session_pct") or 0),
            }
        )

    return {"ok": True, "items": items}


@router.get("/prospeccion/metricas")
async def prospeccion_metricas_dashboard(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("reports.view")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    params: ProspeccionMetricasQuery = Depends(),
) -> dict[str, Any]:
    """Tablero consolidado de métricas: campañas + atribución de frases WhatsApp."""
    effective_timezone, timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    report_zone = ZoneInfo(effective_timezone)
    date_from_dt, date_to_exclusive = local_date_range_to_utc(
        date_from=params.date_from,
        date_to=params.date_to,
        timezone_name=effective_timezone,
    )
    date_to_dt = (
        (date_to_exclusive - timedelta(microseconds=1)) if date_to_exclusive is not None else None
    )
    if date_from_dt and date_to_dt and date_from_dt > date_to_dt:
        raise HTTPException(status_code=400, detail="metricas_date_range_invalid")

    campaign_rows: list[dict[str, Any]] = []
    try:
        campaign_page_size = max(1, min(params.limit, 1000))
        campaign_offset = 0
        while True:
            page_rows = await repo.get_prospeccion_campana_template_atribucion_rango(
                usuario_token=user_token,
                organizacion_id=organizacion_id,
                campana_id=params.campana_id,
                date_from_iso=date_from_dt.isoformat() if date_from_dt else None,
                date_to_iso=date_to_dt.isoformat() if date_to_dt else None,
                limit=campaign_page_size,
                offset=campaign_offset,
            )
            if not page_rows:
                break
            campaign_rows.extend(page_rows)
            if params.lite:
                break
            if len(page_rows) < campaign_page_size:
                break
            campaign_offset += len(page_rows)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    campana_name_map: dict[str, str] = {}
    campana_ids: set[str] = set()
    for row in campaign_rows:
        campana_id_raw = row.get("campana_id")
        if campana_id_raw:
            campana_ids.add(str(campana_id_raw))

    if campana_ids:
        try:
            campanas = await repo.list_campaigns(organizacion_id=organizacion_id)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        for campana in campanas:
            campana_id = str(campana.get("id"))
            if campana_id in campana_ids:
                campana_name = _clean_text(campana.get("nombre"))
                if campana_name:
                    campana_name_map[campana_id] = campana_name

    campaign_items: list[dict[str, Any]] = []
    for row in campaign_rows:
        campana_id_raw = row.get("campana_id")
        campana_id_value = str(campana_id_raw) if campana_id_raw else None
        campana_nombre = _clean_text(row.get("campana_nombre")) or (
            campana_name_map.get(campana_id_value or "")
        )
        item = {
            "campana_id": campana_id_value,
            "campana_nombre": campana_nombre,
            "canal": row.get("canal"),
            "template_id": row.get("template_id"),
            "template_slug": row.get("template_slug"),
            "template_nombre": row.get("template_nombre"),
            "twilio_content_sid": row.get("twilio_content_sid"),
            "envios_totales": int(row.get("envios_totales") or 0),
            "envios_enviados": int(row.get("envios_enviados") or 0),
            "envios_entregados": int(row.get("envios_entregados") or 0),
            "envios_fallidos": int(row.get("envios_fallidos") or 0),
            "envios_omitidos": int(row.get("envios_omitidos") or 0),
            "envios_respondidos": int(row.get("envios_respondidos") or 0),
            "envios_pendientes": int(row.get("envios_pendientes") or 0),
            "envios_procesando": int(row.get("envios_procesando") or 0),
            "envios_enviados_puros": int(row.get("envios_enviados_puros") or 0),
            "brevo_aperturas": int(row.get("brevo_aperturas") or 0),
            "brevo_clicks": int(row.get("brevo_clicks") or 0),
            "sesiones_utm": int(row.get("sesiones_utm") or 0),
            "tasa_entrega_pct": float(row.get("tasa_entrega_pct") or 0),
            "tasa_respuesta_pct": float(row.get("tasa_respuesta_pct") or 0),
            "click_to_session_pct": float(row.get("click_to_session_pct") or 0),
        }
        if params.canal != "todos" and _clean_text(item.get("canal")) != params.canal:
            continue
        campaign_items.append(item)

    campaign_summary = {
        "envios_totales": sum(int(item["envios_totales"]) for item in campaign_items),
        "envios_enviados": sum(int(item["envios_enviados"]) for item in campaign_items),
        "envios_entregados": sum(int(item["envios_entregados"]) for item in campaign_items),
        "envios_respondidos": sum(int(item["envios_respondidos"]) for item in campaign_items),
        "brevo_aperturas": sum(int(item["brevo_aperturas"]) for item in campaign_items),
        "brevo_clicks": sum(int(item["brevo_clicks"]) for item in campaign_items),
        "sesiones_utm": sum(int(item["sesiones_utm"]) for item in campaign_items),
    }
    campaign_summary["tasa_entrega_pct"] = round(
        (campaign_summary["envios_entregados"] / campaign_summary["envios_totales"] * 100)
        if campaign_summary["envios_totales"] > 0
        else 0.0,
        2,
    )
    campaign_summary["tasa_respuesta_pct"] = round(
        (campaign_summary["envios_respondidos"] / campaign_summary["envios_totales"] * 100)
        if campaign_summary["envios_totales"] > 0
        else 0.0,
        2,
    )
    campaign_timeseries: list[dict[str, Any]] = []
    if params.include_campaign_timeseries and not params.lite:
        campaign_timeseries_raw: dict[str, dict[str, int]] = defaultdict(
            lambda: {
                "envios_totales": 0,
                "envios_enviados": 0,
                "envios_entregados": 0,
                "envios_respondidos": 0,
                "envios_fallidos": 0,
                "envios_omitidos": 0,
            }
        )
        batches_rows: list[dict[str, Any]] = []
        try:
            batch_page_size = 500
            batch_offset = 0
            while True:
                batch_page, batch_total = await repo.list_contact_batches(
                    usuario_token=user_token,
                    limit=batch_page_size,
                    offset=batch_offset,
                    campana_id=params.campana_id,
                    order="creado_en.asc",
                )
                if not batch_page:
                    break
                batches_rows.extend(batch_page)
                batch_offset += len(batch_page)
                if len(batch_page) < batch_page_size or batch_offset >= batch_total:
                    break
        except CRMRepositoryError as exc:
            logger.warning("prospeccion.metricas.batches_fetch_failed", extra={"error": str(exc)})
            batches_rows = []
        batch_ids_for_series: list[UUID] = []
        for row in batches_rows:
            raw_batch_id = row.get("id")
            if not raw_batch_id:
                continue
            try:
                batch_ids_for_series.append(UUID(str(raw_batch_id)))
            except (TypeError, ValueError):
                continue
        if batch_ids_for_series:
            envios_rows: list[dict[str, Any]] = []
            responded_envio_days: dict[str, str] = {}
            try:
                batch_chunk_size = 200
                envios_page_size = 1000
                for idx in range(0, len(batch_ids_for_series), batch_chunk_size):
                    batch_chunk = batch_ids_for_series[idx : idx + batch_chunk_size]
                    page_offset = 0
                    while True:
                        chunk_rows = await repo.list_contact_envios_for_batches(
                            usuario_token=user_token,
                            batch_ids=batch_chunk,
                            canal=None if params.canal == "todos" else params.canal,
                            limit=envios_page_size,
                            offset=page_offset,
                        )
                        if not chunk_rows:
                            break
                        envios_rows.extend(chunk_rows)
                        if len(chunk_rows) < envios_page_size:
                            break
                        page_offset += len(chunk_rows)
                    if page_offset > 0:
                        logger.info(
                            "prospeccion.metricas.envios_series_chunk_paginated",
                            extra={
                                "chunk_index": int(idx / batch_chunk_size),
                                "chunk_batch_count": len(batch_chunk),
                                "pages_fetched": int(page_offset / envios_page_size) + 1,
                            },
                        )
            except CRMRepositoryError as exc:
                logger.warning("prospeccion.metricas.envios_series_fetch_failed", extra={"error": str(exc)})
                envios_rows = []
            try:
                batch_chunk_size = 200
                logs_page_size = 1000
                response_actions = {"reply_inbound", "respondido"}
                for idx in range(0, len(batch_ids_for_series), batch_chunk_size):
                    batch_chunk = batch_ids_for_series[idx : idx + batch_chunk_size]
                    page_offset = 0
                    while True:
                        log_rows = await repo.list_contact_logs_for_batches(
                            usuario_token=user_token,
                            batch_ids=batch_chunk,
                            canal=None if params.canal == "todos" else params.canal,
                            limit=logs_page_size,
                            offset=page_offset,
                        )
                        if not log_rows:
                            break
                        for log_row in log_rows:
                            action = (_clean_text(log_row.get("accion")) or "").strip().lower()
                            if action not in response_actions:
                                continue
                            envio_id = _clean_text(log_row.get("envio_id"))
                            if not envio_id:
                                continue
                            log_ts = _parse_datetime(log_row.get("creado_en"))
                            if log_ts is None:
                                continue
                            if date_from_dt and log_ts < date_from_dt:
                                continue
                            if date_to_dt and log_ts > date_to_dt:
                                continue
                            # Conservar la primera respuesta del envio para series diarias.
                            if envio_id not in responded_envio_days:
                                responded_envio_days[envio_id] = log_ts.astimezone(report_zone).date().isoformat()
                        if len(log_rows) < logs_page_size:
                            break
                        page_offset += len(log_rows)
            except CRMRepositoryError as exc:
                logger.warning("prospeccion.metricas.logs_series_fetch_failed", extra={"error": str(exc)})
            unique_envios: dict[str, dict[str, Any]] = {}
            for row in envios_rows:
                envio_id_raw = row.get("id")
                if envio_id_raw is None:
                    continue
                unique_envios[str(envio_id_raw)] = row
            envios_rows = list(unique_envios.values())
            sent_states = {"enviado", "entregado", "leido", "completado", "respondido"}
            delivered_states = {"entregado", "leido", "completado", "respondido"}
            failed_states = {"fallido", "error", "failed"}
            omitted_states = {"omitido", "skipped", "suprimido", "suppressed"}
            for envio in envios_rows:
                event_ts = (
                    _parse_datetime(envio.get("procesado_en"))
                    or _parse_datetime(envio.get("creado_en"))
                    or _parse_datetime(envio.get("programado_en"))
                )
                if event_ts is None:
                    continue
                if date_from_dt and event_ts < date_from_dt:
                    continue
                if date_to_dt and event_ts > date_to_dt:
                    continue
                day_key = event_ts.astimezone(report_zone).date().isoformat()
                bucket = campaign_timeseries_raw[day_key]
                bucket["envios_totales"] += 1
                estado = (_clean_text(envio.get("estado")) or "").lower()
                if estado in sent_states:
                    bucket["envios_enviados"] += 1
                if estado in delivered_states:
                    bucket["envios_entregados"] += 1
                if estado in failed_states:
                    bucket["envios_fallidos"] += 1
                if estado in omitted_states:
                    bucket["envios_omitidos"] += 1
                envio_id_key = _clean_text(envio.get("id"))
                if estado == "respondido" and (not envio_id_key or envio_id_key not in responded_envio_days):
                    bucket["envios_respondidos"] += 1
            # Si existe log de reply_inbound/respondido, usar fecha real de respuesta para la serie.
            for day_key in responded_envio_days.values():
                campaign_timeseries_raw[day_key]["envios_respondidos"] += 1
        campaign_timeseries = [
            {"fecha": day, **metrics}
            for day, metrics in sorted(campaign_timeseries_raw.items(), key=lambda item: item[0])
        ]

    frase_events: list[dict[str, Any]] = []
    try:
        frase_page_size = max(1, min(params.limit, 1000))
        frase_offset = 0
        while True:
            page_rows = await repo.list_whatsapp_atribucion_eventos_for_metrics(
                usuario_token=user_token,
                limit=frase_page_size,
                offset=frase_offset,
                date_from_iso=date_from_dt.isoformat() if date_from_dt else None,
                date_to_iso=date_to_dt.isoformat() if date_to_dt else None,
                campana_publicitaria=_clean_text(params.campana_publicitaria),
                regla_id=params.regla_id,
            )
            if not page_rows:
                break
            frase_events.extend(page_rows)
            if params.lite:
                break
            if len(page_rows) < frase_page_size:
                break
            frase_offset += len(page_rows)
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    rule_name_map: dict[str, str] = {}
    try:
        rules_for_map, _ = await repo.list_whatsapp_atribucion_reglas(
            usuario_token=user_token,
            limit=200 if params.lite else 500,
            offset=0,
            include_historial=True,
        )
    except CRMRepositoryError:
        rules_for_map = []
    for rule in rules_for_map:
        rule_id_value = _clean_text(rule.get("id"))
        rule_name = _clean_text(rule.get("nombre_regla"))
        if rule_id_value and rule_name:
            rule_name_map[rule_id_value] = rule_name

    conversation_ids = {
        _clean_text(row.get("conversacion_id"))
        for row in frase_events
        if _clean_text(row.get("conversacion_id"))
    }
    opportunities: list[dict[str, Any]] = []
    if not params.lite:
        try:
            opportunity_page_size = 1000
            opportunity_offset = 0
            conversation_id_list = [value for value in conversation_ids if value]
            while True:
                page_rows = await repo.list_opportunities_by_conversation_ids(
                    organizacion_id=organizacion_id,
                    conversation_ids=conversation_id_list,
                    limit=opportunity_page_size,
                    offset=opportunity_offset,
                )
                if not page_rows:
                    break
                opportunities.extend(page_rows)
                if len(page_rows) < opportunity_page_size:
                    break
                opportunity_offset += len(page_rows)
        except CRMRepositoryError as exc:
            logger.warning("prospeccion.metricas.opportunities_by_conversation_failed", extra={"error": str(exc)})
            opportunities = []

    opp_by_conversation: dict[str, dict[str, Any]] = {}
    for opportunity in opportunities:
        conversation_id_value = _extract_opportunity_conversation_id(opportunity)
        if not conversation_id_value or conversation_id_value in opp_by_conversation:
            continue
        opp_by_conversation[conversation_id_value] = opportunity

    by_channel: dict[str, dict[str, Any]] = {}
    by_rule: dict[str, dict[str, Any]] = {}

    for row in frase_events:
        conversation_id_value = _clean_text(row.get("conversacion_id"))
        contact_id_value = _clean_text(row.get("contacto_id"))
        channel_value = _clean_text(row.get("canal_publicitario")) or "sin_canal"
        rule_id_value = _clean_text(row.get("regla_id"))
        rule_key = rule_id_value or f"sin_regla::{channel_value}"
        rule_name = rule_name_map.get(rule_id_value or "") or "Sin regla"
        campana_publicitaria_value = _clean_text(row.get("campana_publicitaria"))
        if params.canal == "whatsapp" or params.canal == "todos":
            pass
        else:
            continue

        channel_bucket = by_channel.setdefault(
            channel_value,
            {
                "canal_publicitario": channel_value,
                "conversaciones": set(),
                "contactos": set(),
                "oportunidades": set(),
                "monto_estimado_total": 0.0,
            },
        )
        rule_bucket = by_rule.setdefault(
            rule_key,
            {
                "regla_id": rule_id_value,
                "regla_nombre": rule_name,
                "canal_publicitario": channel_value,
                "campana_publicitaria": campana_publicitaria_value,
                "conversaciones": set(),
                "contactos": set(),
                "oportunidades": set(),
                "monto_estimado_total": 0.0,
            },
        )

        if conversation_id_value:
            channel_bucket["conversaciones"].add(conversation_id_value)
            rule_bucket["conversaciones"].add(conversation_id_value)
        if contact_id_value:
            channel_bucket["contactos"].add(contact_id_value)
            rule_bucket["contactos"].add(contact_id_value)

        opportunity = opp_by_conversation.get(conversation_id_value or "")
        if opportunity and conversation_id_value:
            channel_bucket["oportunidades"].add(conversation_id_value)
            rule_bucket["oportunidades"].add(conversation_id_value)
            try:
                monto = float(opportunity.get("monto_estimado") or 0)
            except (TypeError, ValueError):
                monto = 0.0
            channel_bucket["monto_estimado_total"] += monto
            rule_bucket["monto_estimado_total"] += monto

    by_channel_items: list[dict[str, Any]] = []
    if params.include_whatsapp_channels:
        for bucket in by_channel.values():
            conversaciones = len(bucket["conversaciones"])
            oportunidades_count = len(bucket["oportunidades"])
            by_channel_items.append(
                {
                    "canal_publicitario": bucket["canal_publicitario"],
                    "conversaciones_atribuidas": conversaciones,
                    "contactos_unicos": len(bucket["contactos"]),
                    "oportunidades_creadas": oportunidades_count,
                    "tasa_conversacion_oportunidad_pct": round(
                        (oportunidades_count / conversaciones * 100) if conversaciones > 0 else 0.0,
                        2,
                    ),
                    "monto_estimado_total": round(float(bucket["monto_estimado_total"]), 2),
                }
            )

    by_rule_items: list[dict[str, Any]] = []
    for bucket in by_rule.values():
        conversaciones = len(bucket["conversaciones"])
        oportunidades_count = len(bucket["oportunidades"])
        by_rule_items.append(
            {
                "regla_id": bucket["regla_id"],
                "regla_nombre": bucket["regla_nombre"],
                "canal_publicitario": bucket["canal_publicitario"],
                "campana_publicitaria": bucket["campana_publicitaria"],
                "conversaciones_atribuidas": conversaciones,
                "contactos_unicos": len(bucket["contactos"]),
                "oportunidades_creadas": oportunidades_count,
                "tasa_conversacion_oportunidad_pct": round(
                    (oportunidades_count / conversaciones * 100) if conversaciones > 0 else 0.0,
                    2,
                ),
                "monto_estimado_total": round(float(bucket["monto_estimado_total"]), 2),
            }
        )

    by_channel_items.sort(key=lambda item: item["conversaciones_atribuidas"], reverse=True)
    by_rule_items.sort(key=lambda item: item["conversaciones_atribuidas"], reverse=True)

    total_conversations = len({cid for cid in conversation_ids if cid})
    total_contacts = len(
        {
            _clean_text(row.get("contacto_id"))
            for row in frase_events
            if _clean_text(row.get("contacto_id"))
        }
    )
    total_opportunities = len(opp_by_conversation)
    total_amount = round(
        float(sum(float(item["monto_estimado_total"]) for item in by_channel_items)),
        2,
    )
    frases_timeseries: list[dict[str, Any]] = []
    if params.include_whatsapp_timeseries and not params.lite:
        frases_timeseries_raw: dict[str, dict[str, float]] = defaultdict(
            lambda: {
                "conversaciones_atribuidas": 0,
                "oportunidades_creadas": 0,
                "monto_estimado_total": 0.0,
            }
        )
    for event in frase_events:
        event_ts = _parse_datetime(event.get("creado_en"))
        if event_ts is None:
            continue
        day_key = event_ts.astimezone(report_zone).date().isoformat()
        bucket = frases_timeseries_raw[day_key]
        bucket["conversaciones_atribuidas"] += 1
        conversation_id_value = _clean_text(event.get("conversacion_id"))
        if conversation_id_value and conversation_id_value in opp_by_conversation:
            bucket["oportunidades_creadas"] += 1
            try:
                bucket["monto_estimado_total"] += float(
                    opp_by_conversation[conversation_id_value].get("monto_estimado") or 0
                )
            except (TypeError, ValueError):
                pass
        frases_timeseries = [
            {
                "fecha": day,
                "conversaciones_atribuidas": int(values["conversaciones_atribuidas"]),
                "oportunidades_creadas": int(values["oportunidades_creadas"]),
                "monto_estimado_total": round(float(values["monto_estimado_total"]), 2),
            }
            for day, values in sorted(frases_timeseries_raw.items(), key=lambda item: item[0])
        ]

    return {
        "ok": True,
        "filters": {
            "date_from": date_from_dt.isoformat() if date_from_dt else None,
            "date_to": date_to_dt.isoformat() if date_to_dt else None,
            "effective_timezone": effective_timezone,
            "timezone_source": timezone_source,
            "campana_id": str(params.campana_id) if params.campana_id else None,
            "canal": params.canal,
            "campana_publicitaria": _clean_text(params.campana_publicitaria),
            "regla_id": str(params.regla_id) if params.regla_id else None,
        },
        "campanas": {
            "summary": campaign_summary,
            "items": campaign_items,
            "timeseries": campaign_timeseries,
        },
        "frases_whatsapp": {
            "summary": {
                "conversaciones_atribuidas": total_conversations,
                "contactos_unicos": total_contacts,
                "oportunidades_creadas": total_opportunities,
                "tasa_conversacion_oportunidad_pct": round(
                    (total_opportunities / total_conversations * 100) if total_conversations > 0 else 0.0,
                    2,
                ),
                "monto_estimado_total": total_amount,
            },
            "by_channel": by_channel_items,
            "by_rule": by_rule_items,
            "timeseries": frases_timeseries,
        },
    }


@router.get("/prospeccion/metricas/export/xlsx")
async def prospeccion_metricas_export_xlsx(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("reports.view")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    params: ProspeccionMetricasQuery = Depends(),
) -> Response:
    if Workbook is None:
        raise HTTPException(status_code=500, detail="openpyxl_required")

    payload = await prospeccion_metricas_dashboard(
        repo=repo,
        _="reports.view",
        user_token=user_token,
        organizacion_id=organizacion_id,
        params=params,
    )

    workbook = Workbook()
    summary_sheet = workbook.active
    summary_sheet.title = "Resumen"
    summary_sheet.append(["Seccion", "Metrica", "Valor"])

    camp_summary = _ensure_dict(_ensure_dict(payload.get("campanas"), default={}).get("summary"), default={})
    frases_summary = _ensure_dict(_ensure_dict(payload.get("frases_whatsapp"), default={}).get("summary"), default={})
    filters_summary = _ensure_dict(payload.get("filters"), default={})
    website_status_counts: dict[str, int] = {}

    for website_status in ("pendiente", "sin_sitio", "valido", "dudoso", "invalido", "error"):
        try:
            _, website_total = await repo.list_prospectos(
                usuario_token=user_token,
                organizacion_id=organizacion_id,
                limit=1,
                offset=0,
                website_lookup_status=website_status,
                date_from=params.date_from,
                date_to=params.date_to,
            )
        except CRMRepositoryError:
            website_total = 0
        website_status_counts[website_status] = int(website_total or 0)

    for key in ("date_from", "date_to", "campana_id", "canal", "campana_publicitaria", "regla_id"):
        summary_sheet.append(["filtros", key, filters_summary.get(key)])

    for key in (
        "envios_totales",
        "envios_enviados",
        "envios_entregados",
        "envios_respondidos",
        "brevo_aperturas",
        "brevo_clicks",
        "sesiones_utm",
        "tasa_entrega_pct",
        "tasa_respuesta_pct",
    ):
        summary_sheet.append(["campanas", key, camp_summary.get(key)])

    for key in (
        "conversaciones_atribuidas",
        "contactos_unicos",
        "oportunidades_creadas",
        "tasa_conversacion_oportunidad_pct",
        "monto_estimado_total",
    ):
        summary_sheet.append(["frases_whatsapp", key, frases_summary.get(key)])

    for status in ("pendiente", "sin_sitio", "valido", "dudoso", "invalido", "error"):
        summary_sheet.append(["sitios_web", f"website_lookup_{status}", website_status_counts.get(status, 0)])

    campanas_sheet = workbook.create_sheet("Campanas")
    campanas_sheet.append(
        [
            "campana_id",
            "campana_nombre",
            "canal",
            "template_id",
            "template_slug",
            "template_nombre",
            "envios_totales",
            "envios_enviados",
            "envios_entregados",
            "envios_fallidos",
            "envios_omitidos",
            "envios_respondidos",
            "brevo_aperturas",
            "brevo_clicks",
            "sesiones_utm",
            "tasa_entrega_pct",
            "tasa_respuesta_pct",
            "click_to_session_pct",
        ]
    )
    campanas_items = _ensure_dict(payload.get("campanas"), default={}).get("items")
    if not isinstance(campanas_items, list):
        campanas_items = []
    for item in campanas_items:
        row = _ensure_dict(item, default={})
        campanas_sheet.append(
            [
                row.get("campana_id"),
                row.get("campana_nombre"),
                row.get("canal"),
                row.get("template_id"),
                row.get("template_slug"),
                row.get("template_nombre"),
                row.get("envios_totales"),
                row.get("envios_enviados"),
                row.get("envios_entregados"),
                row.get("envios_fallidos"),
                row.get("envios_omitidos"),
                row.get("envios_respondidos"),
                row.get("brevo_aperturas"),
                row.get("brevo_clicks"),
                row.get("sesiones_utm"),
                row.get("tasa_entrega_pct"),
                row.get("tasa_respuesta_pct"),
                row.get("click_to_session_pct"),
            ]
        )

    campanas_series_sheet = workbook.create_sheet("CampanasSeries")
    campanas_series_sheet.append(
        ["fecha", "envios_totales", "envios_enviados", "envios_entregados", "envios_respondidos"]
    )
    campanas_timeseries = _ensure_dict(payload.get("campanas"), default={}).get("timeseries")
    if not isinstance(campanas_timeseries, list):
        campanas_timeseries = []
    for item in campanas_timeseries:
        row = _ensure_dict(item, default={})
        campanas_series_sheet.append(
            [
                row.get("fecha"),
                row.get("envios_totales"),
                row.get("envios_enviados"),
                row.get("envios_entregados"),
                row.get("envios_respondidos"),
            ]
        )

    frases_channel_sheet = workbook.create_sheet("FrasesPorCanal")
    frases_channel_sheet.append(
        [
            "canal_publicitario",
            "conversaciones_atribuidas",
            "contactos_unicos",
            "oportunidades_creadas",
            "tasa_conversacion_oportunidad_pct",
            "monto_estimado_total",
        ]
    )
    frases_by_channel = _ensure_dict(payload.get("frases_whatsapp"), default={}).get("by_channel")
    if not isinstance(frases_by_channel, list):
        frases_by_channel = []
    for item in frases_by_channel:
        row = _ensure_dict(item, default={})
        frases_channel_sheet.append(
            [
                row.get("canal_publicitario"),
                row.get("conversaciones_atribuidas"),
                row.get("contactos_unicos"),
                row.get("oportunidades_creadas"),
                row.get("tasa_conversacion_oportunidad_pct"),
                row.get("monto_estimado_total"),
            ]
        )

    frases_rule_sheet = workbook.create_sheet("FrasesPorRegla")
    frases_rule_sheet.append(
        [
            "regla_id",
            "regla_nombre",
            "canal_publicitario",
            "campana_publicitaria",
            "conversaciones_atribuidas",
            "contactos_unicos",
            "oportunidades_creadas",
            "tasa_conversacion_oportunidad_pct",
            "monto_estimado_total",
        ]
    )
    frases_by_rule = _ensure_dict(payload.get("frases_whatsapp"), default={}).get("by_rule")
    if not isinstance(frases_by_rule, list):
        frases_by_rule = []
    for item in frases_by_rule:
        row = _ensure_dict(item, default={})
        frases_rule_sheet.append(
            [
                row.get("regla_id"),
                row.get("regla_nombre"),
                row.get("canal_publicitario"),
                row.get("campana_publicitaria"),
                row.get("conversaciones_atribuidas"),
                row.get("contactos_unicos"),
                row.get("oportunidades_creadas"),
                row.get("tasa_conversacion_oportunidad_pct"),
                row.get("monto_estimado_total"),
            ]
        )

    frases_series_sheet = workbook.create_sheet("FrasesSeries")
    frases_series_sheet.append(
        ["fecha", "conversaciones_atribuidas", "oportunidades_creadas", "monto_estimado_total"]
    )
    frases_timeseries = _ensure_dict(payload.get("frases_whatsapp"), default={}).get("timeseries")
    if not isinstance(frases_timeseries, list):
        frases_timeseries = []
    for item in frases_timeseries:
        row = _ensure_dict(item, default={})
        frases_series_sheet.append(
            [
                row.get("fecha"),
                row.get("conversaciones_atribuidas"),
                row.get("oportunidades_creadas"),
                row.get("monto_estimado_total"),
            ]
        )

    output = io.BytesIO()
    workbook.save(output)
    output.seek(0)

    filename = f"prospeccion_metricas_{datetime.now(tz=timezone.utc).strftime('%Y%m%d_%H%M%S')}.xlsx"
    return Response(
        content=output.getvalue(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


@router.get("/prospeccion/campanas/{campana_id}/duplicar")
async def prospeccion_campana_duplicar_defaults(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    campana_id: UUID,
) -> dict[str, Any]:
    """Obtiene el preset del lote más reciente para duplicar una campaña."""

    campana = await repo.get_campaign(organizacion_id=organizacion_id, campana_id=campana_id)
    if not campana:
        raise HTTPException(status_code=404, detail="campana_not_found")

    batches, _ = await repo.list_contact_batches(
        usuario_token=user_token,
        limit=1,
        offset=0,
        campana_id=campana_id,
        order="creado_en.desc",
    )
    if not batches:
        raise HTTPException(status_code=404, detail="campana_without_batches")
    base_batch = batches[0]
    metadata = _ensure_dict(base_batch.get("metadata"), default={})
    canales_config = _ensure_dict(metadata.get("canales_config"), default={})
    programacion = _ensure_dict(base_batch.get("programacion"), default={})
    batch_metadata = _ensure_dict(base_batch.get("metadata"), default={})
    separacion_segundos_raw = batch_metadata.get("separacion_segundos")
    try:
        separacion_segundos = (
            max(MIN_PROSPECCION_SEPARACION_SEGUNDOS, int(separacion_segundos_raw))
            if separacion_segundos_raw is not None
            else MIN_PROSPECCION_SEPARACION_SEGUNDOS
        )
    except (TypeError, ValueError):
        separacion_segundos = MIN_PROSPECCION_SEPARACION_SEGUNDOS
    filtros = base_batch.get("filtros") if isinstance(base_batch.get("filtros"), dict) else {}
    lista_id = base_batch.get("lista_id")
    source: Literal["selected", "lista", "filters"] = "selected"
    if lista_id:
        source = "lista"
    elif filtros:
        source = "filters"

    canales_defaults: dict[str, Any] = {}
    for canal, config in canales_config.items():
        if not isinstance(config, dict):
            continue
        canales_defaults[canal] = {
            "templateSlug": config.get("template_slug"),
            "subject": config.get("subject"),
            "body": config.get("body"),
            "message": config.get("message"),
            "schedule": programacion.get(canal),
            "enabled": True,
        }

    defaults = {
        "campana_id": str(campana_id),
        "campana_nombre": campana.get("nombre"),
        "titulo": base_batch.get("titulo"),
        "source": source,
        "lista_id": str(lista_id) if lista_id else None,
        "filtros": filtros or {},
        "canales": canales_defaults,
        "programacion": programacion or {},
        "separacion_segundos": separacion_segundos,
    }
    return {
        "ok": True,
        "campana": {
            "id": str(campana_id),
            "nombre": campana.get("nombre"),
            "descripcion": campana.get("descripcion"),
        },
        "defaults": defaults,
    }


@router.patch("/prospeccion/campanas/{campana_id}")
async def prospeccion_campana_update(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    campana_id: UUID,
    payload: ProspeccionCampanaUpdatePayload,
) -> dict[str, Any]:
    """Edita campaña y, opcionalmente, reconfigura su lote más reciente."""

    campana = await repo.get_campaign(organizacion_id=organizacion_id, campana_id=campana_id)
    if not campana:
        raise HTTPException(status_code=404, detail="campana_not_found")

    campaign_patch: dict[str, Any] = {}
    if payload.campana_nombre is not None:
        campaign_patch["nombre"] = payload.campana_nombre.strip()
    if campaign_patch:
        await repo.update_campaign(
            organizacion_id=organizacion_id,
            campana_id=campana_id,
            payload=campaign_patch,
        )

    has_batch_updates = any(
        value is not None
        for value in (
            payload.batch_titulo,
            payload.lista_id,
            payload.filtros,
            payload.canales,
        )
    )

    batches, _ = await repo.list_contact_batches(
        usuario_token=user_token,
        limit=100,
        offset=0,
        campana_id=campana_id,
        order="creado_en.desc",
    )
    if not batches:
        if has_batch_updates:
            raise HTTPException(status_code=404, detail="campana_without_batches")
        updated = await repo.get_campaign(organizacion_id=organizacion_id, campana_id=campana_id)
        return {
            "ok": True,
            "campana_id": str(campana_id),
            "batch_id": None,
            "campana": {
                "id": str(campana_id),
                "nombre": updated.get("nombre") if updated else campaign_patch.get("nombre"),
            },
        }
    target_batch = None
    for row in batches:
        estado = _clean_text(row.get("estado")) or ""
        if estado.lower() in {"pendiente", "procesando"}:
            target_batch = row
            break
    if target_batch is None:
        target_batch = batches[0]

    batch_id_raw = target_batch.get("id")
    if not batch_id_raw:
        raise HTTPException(status_code=400, detail="batch_not_found")
    batch_id = UUID(str(batch_id_raw))

    template_map: dict[str, dict[str, Any]] = {}
    if payload.canales:
        template_ids = {config.template_id for config in payload.canales if config.template_id}
        if template_ids:
            template_map = await _fetch_contact_templates(
                repo=repo,
                user_token=user_token,
                template_ids=template_ids,
            )
            if payload.campana_id:
                campana_key = str(payload.campana_id)
                for template_id, template in template_map.items():
                    metadata = template.get("metadata") if isinstance(template.get("metadata"), dict) else {}
                    template_campana = _clean_text(metadata.get("campana_id"))
                    if not template_campana:
                        raise HTTPException(
                            status_code=400,
                            detail=f"contact_template_campaign_missing:{template_id}",
                        )
                    if template_campana != campana_key:
                        raise HTTPException(
                            status_code=400,
                            detail=f"contact_template_campaign_mismatch:{template_id}",
                        )
    canales_config, programacion = _resolve_contact_channels(
        ProspectoContactarPayload(
            prospecto_ids=[UUID("00000000-0000-0000-0000-000000000001")],
            campana_id=campana_id,
            lista_id=payload.lista_id,
            filtros=payload.filtros,
            canales=payload.canales,
        ),
        template_map=template_map,
    )
    if not canales_config:
        existing_meta = _ensure_dict(target_batch.get("metadata"), default={})
        existing_canales = _ensure_dict(existing_meta.get("canales_config"), default={})
        canales_config = {k: v for k, v in existing_canales.items() if isinstance(v, dict)}
        programacion = _ensure_dict(target_batch.get("programacion"), default={})
    programacion = await _align_programacion_with_active_campaign_schedule(
        repo=repo,
        user_token=user_token,
        campana_id=campana_id,
        canales=set(canales_config.keys()),
        programacion=programacion,
        separacion_segundos=payload.separacion_segundos,
        exclude_batch_id=batch_id,
    )
    await _apply_default_whatsapp_runtime_template(
        canales_config=canales_config,
        organizacion_id=organizacion_id,
    )
    _assert_whatsapp_template_configured(canales_config)
    if not canales_config:
        raise HTTPException(status_code=400, detail="contact_channels_required")

    selector_filtros: dict[str, Any] = {}
    prospectos: list[dict[str, Any]] = []
    if payload.lista_id:
        lista_row = await repo.get_contact_list(usuario_token=user_token, lista_id=payload.lista_id)
        if not lista_row:
            raise HTTPException(status_code=404, detail="contact_list_not_found")
        filtros_data = _ensure_dict(lista_row.get("filtros"), default={})
        filtros_fuente = ProspectoFiltroPayload.model_validate(filtros_data)
        repo_kwargs = _prospecto_filters_to_kwargs(filtros_fuente)
        prospectos, total = await repo.list_prospectos(
            usuario_token=user_token,
            organizacion_id=organizacion_id,
            limit=MAX_PROSPECCION_BATCH,
            offset=0,
            order="creado_en.desc",
            **repo_kwargs,
        )
        if total > MAX_PROSPECCION_BATCH:
            raise HTTPException(status_code=400, detail="prospecto_batch_limit_exceeded")
        selector_filtros = filtros_data
    elif payload.filtros:
        repo_kwargs = _prospecto_filters_to_kwargs(payload.filtros)
        prospectos, total = await repo.list_prospectos(
            usuario_token=user_token,
            organizacion_id=organizacion_id,
            limit=MAX_PROSPECCION_BATCH,
            offset=0,
            order="creado_en.desc",
            **repo_kwargs,
        )
        if total > MAX_PROSPECCION_BATCH:
            raise HTTPException(status_code=400, detail="prospecto_batch_limit_exceeded")
        selector_filtros = payload.filtros.model_dump(exclude_none=True)
    else:
        current_envios = await _list_batch_envios_all(repo=repo, user_token=user_token, batch_id=batch_id)
        detail_by_prospect: dict[str, dict[str, Any]] = {}
        for envio in current_envios:
            pid = _clean_text(envio.get("prospecto_id"))
            if not pid:
                continue
            detalle = envio.get("detalle") if isinstance(envio.get("detalle"), dict) else {}
            detail_by_prospect.setdefault(pid, detalle)
        for pid, detalle in detail_by_prospect.items():
            prospectos.append(
                {
                    "id": pid,
                    "display_name": detalle.get("display_name"),
                    "actividad": detalle.get("actividad"),
                    "email": detalle.get("email"),
                    "phone": detalle.get("phone"),
                    "phone_e164": detalle.get("phone"),
                    "whatsapp_permitido": detalle.get("whatsapp_permitido"),
                    "llamada_permitida": detalle.get("llamada_permitida"),
                    "carrier_type": detalle.get("carrier_type"),
                    "segmento": detalle.get("segmento"),
                    "metadata": {"stage": detalle.get("stage")},
                }
            )
        selector_filtros = _ensure_dict(target_batch.get("filtros"), default={})

    prospectos, bloqueados = _split_recontact_blocked_prospectos(prospectos)
    if not prospectos:
        raise HTTPException(status_code=400, detail="prospectos_not_found")

    existing_batch_metadata = _ensure_dict(target_batch.get("metadata"), default={})
    if payload.separacion_segundos is not None:
        separacion_segundos = payload.separacion_segundos
    else:
        try:
            separacion_segundos = max(
                MIN_PROSPECCION_SEPARACION_SEGUNDOS,
                int(existing_batch_metadata.get("separacion_segundos")),
            )
        except (TypeError, ValueError):
            separacion_segundos = MIN_PROSPECCION_SEPARACION_SEGUNDOS

    existing_envios = await _list_batch_envios_all(repo=repo, user_token=user_token, batch_id=batch_id)
    for envio in existing_envios:
        envio_id_raw = envio.get("id")
        if not envio_id_raw:
            continue
        estado = _clean_text(envio.get("estado")) or "pendiente"
        if estado != "pendiente":
            continue
        try:
            envio_id = UUID(str(envio_id_raw))
        except (TypeError, ValueError):
            continue
        await repo.update_contact_envio(
            usuario_token=user_token,
            envio_id=envio_id,
            payload={
                "estado": "cancelado",
                "detalle": _merge_detalle(
                    envio.get("detalle") if isinstance(envio.get("detalle"), dict) else {},
                    {"reason": "campana_editada"},
                ),
                "procesado_en": datetime.now(UTC).isoformat(),
                "error": None,
            },
        )

    prospecto_ids: list[UUID] = []
    for item in prospectos:
        raw_id = item.get("id")
        if not raw_id:
            continue
        try:
            prospecto_ids.append(UUID(str(raw_id)))
        except (TypeError, ValueError):
            continue

    suppressions = await repo.list_active_contact_suppressions_for_prospectos(
        usuario_token=user_token,
        prospecto_ids=prospecto_ids,
        canales=list(canales_config.keys()),
    )
    suppression_map = _build_suppression_channel_map(suppressions)
    prospectos = _attach_suppressions_to_prospectos(prospectos, suppression_map)

    new_entries, suppressed_by_channel = _build_contact_envios_entries(
        batch_id=batch_id,
        prospectos=prospectos,
        canales=canales_config,
        programacion=programacion or None,
        separacion_segundos=separacion_segundos,
    )
    created_envios = await repo.insert_contact_envios(usuario_token=user_token, entries=new_entries)

    metadata_existing = existing_batch_metadata
    metadata_existing["canales_config"] = canales_config
    if separacion_segundos is not None:
        metadata_existing["separacion_segundos"] = separacion_segundos
    if bloqueados:
        metadata_existing["recontacto_bloqueados"] = {"total": len(bloqueados)}
    if suppressed_by_channel:
        metadata_existing["suppressions_bloqueados"] = {
            canal: len(ids) for canal, ids in suppressed_by_channel.items()
        }

    batch_patch: dict[str, Any] = {
        "canales": list(canales_config.keys()),
        "filtros": selector_filtros,
        "total_prospectos": len(prospectos),
        "estado": "pendiente",
        "metadata": metadata_existing,
    }
    if payload.batch_titulo is not None:
        batch_patch["titulo"] = payload.batch_titulo.strip() or None
    if payload.lista_id is not None:
        batch_patch["lista_id"] = str(payload.lista_id)
    if programacion:
        batch_patch["programacion"] = programacion
    else:
        batch_patch["programacion"] = {}

    updated_batch = await repo.update_contact_batch(
        usuario_token=user_token,
        batch_id=batch_id,
        payload=batch_patch,
    )
    resumen = _build_contact_resumen(created_envios)
    omitidos = []
    if bloqueados:
        omitidos.append({"motivo": "convertido_contacto", "prospecto_ids": bloqueados, "total": len(bloqueados)})
    for canal, ids in suppressed_by_channel.items():
        omitidos.append({"motivo": f"opt_out_{canal}", "prospecto_ids": ids, "total": len(ids)})

    return {
        "ok": True,
        "campana_id": str(campana_id),
        "batch_id": str(batch_id),
        "batch": updated_batch,
        "contactos": resumen,
        "omitidos": omitidos,
    }


@router.delete("/prospeccion/campanas/{campana_id}")
async def prospeccion_campana_delete(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    campana_id: UUID,
    payload: ProspeccionCampanaDeletePayload = Body(default=ProspeccionCampanaDeletePayload()),
) -> dict[str, Any]:
    """Archiva campaña y cancela pendientes de sus lotes (eliminación lógica)."""

    campana = await repo.get_campaign(organizacion_id=organizacion_id, campana_id=campana_id)
    if not campana:
        raise HTTPException(status_code=404, detail="campana_not_found")

    batches, _ = await repo.list_contact_batches(
        usuario_token=user_token,
        limit=500,
        offset=0,
        campana_id=campana_id,
        order="creado_en.desc",
    )
    cancelled = 0
    for batch in batches:
        batch_id_raw = batch.get("id")
        if not batch_id_raw:
            continue
        try:
            batch_id = UUID(str(batch_id_raw))
        except (TypeError, ValueError):
            continue
        envios = await _list_batch_envios_all(repo=repo, user_token=user_token, batch_id=batch_id)
        for envio in envios:
            if _clean_text(envio.get("estado")) != "pendiente":
                continue
            envio_id_raw = envio.get("id")
            if not envio_id_raw:
                continue
            try:
                envio_id = UUID(str(envio_id_raw))
            except (TypeError, ValueError):
                continue
            await repo.update_contact_envio(
                usuario_token=user_token,
                envio_id=envio_id,
                payload={
                    "estado": "cancelado",
                    "detalle": _merge_detalle(
                        envio.get("detalle") if isinstance(envio.get("detalle"), dict) else {},
                        {"reason": "campana_eliminada"},
                    ),
                    "procesado_en": datetime.now(UTC).isoformat(),
                    "error": None,
                },
            )
            cancelled += 1
        batch_meta = _ensure_dict(batch.get("metadata"), default={})
        batch_meta["deleted"] = True
        batch_meta["deleted_at"] = datetime.now(UTC).isoformat()
        await repo.update_contact_batch(
            usuario_token=user_token,
            batch_id=batch_id,
            payload={"estado": "cancelado", "metadata": batch_meta},
        )

    campana_meta = _ensure_dict(campana.get("metadata"), default={})
    campana_meta["deleted"] = True
    campana_meta["deleted_at"] = datetime.now(UTC).isoformat()
    if payload.hard_delete:
        campana_meta["hard_delete_requested"] = True
    await repo.update_campaign(
        organizacion_id=organizacion_id,
        campana_id=campana_id,
        payload={"metadata": campana_meta},
    )
    return {"ok": True, "campana_id": str(campana_id), "envios_cancelados": cancelled}


@router.get("/prospeccion/prospectos/{prospecto_id}/contactos")
async def listar_contactos_por_prospecto(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    prospecto_id: UUID,
    limit: Annotated[int, Query(ge=1, le=200)] = 100,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> dict[str, Any]:
    """Historial de envíos asociados a un prospecto."""

    try:
        rows, total = await repo.list_contact_envios(
            usuario_token=user_token,
            limit=limit,
            offset=offset,
            prospecto_id=prospecto_id,
            order="creado_en.desc",
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    return {
        "ok": True,
        "items": rows,
        "total": total,
        "limit": limit,
        "offset": offset,
    }


@router.get("/prospeccion/prospectos/{prospecto_id}/audit")
async def listar_audit_por_prospecto(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    prospecto_id: UUID,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
) -> dict[str, Any]:
    try:
        rows = await repo.list_prospecto_audit(
            usuario_token=user_token,
            prospecto_id=prospecto_id,
            limit=limit,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    entries: list[ProspectoAuditEntryResponse] = []
    for row in rows:
        entry_id = _safe_uuid(row.get("id"))
        if entry_id is None:
            continue
        raw_action = str(row.get("accion") or "").lower()
        action: Literal["insert", "update", "delete"]
        if raw_action in {"insert", "delete"}:
            action = raw_action  # type: ignore[assignment]
        else:
            action = "update"
        cambios_value = row.get("cambios")
        cambios_dict = cambios_value if isinstance(cambios_value, dict) else {}
        entries.append(
            ProspectoAuditEntryResponse(
                id=entry_id,
                accion=action,
                cambios=cambios_dict,
                realizado_por=_safe_uuid(row.get("realizado_por")),
                realizado_en=_parse_datetime(row.get("realizado_en")) or datetime.now(timezone.utc),
            )
        )

    return {"ok": True, "items": [entry.model_dump(mode="json") for entry in entries]}


@router.post("/prospeccion/prospectos/{prospecto_id}/convertir-contacto")
async def convertir_prospecto_contacto(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    prospecto_id: UUID,
    payload: ProspectoConvertirPayload,
) -> dict[str, Any]:
    """Crea un contacto CRM a partir de un prospecto y actualiza su metadata."""

    prospecto = await _get_prospecto_or_404(
        repo=repo,
        user_token=user_token,
        prospecto_id=prospecto_id,
    )
    nombre = _clean_text(payload.nombre) or _clean_text(prospecto.get("nombre_comercial")) or _clean_text(prospecto.get("display_name"))
    correo = payload.correo or prospecto.get("email")
    telefono = payload.telefono or prospecto.get("phone_e164") or prospecto.get("phone")
    canal_origen = (payload.canal_origen or "otro").lower()
    source_label = _describe_prospeccion_source(prospecto)
    pipeline_canal_label = _infer_prospeccion_canal_label(prospecto)
    contacto_body = {
        "nombre_completo": nombre,
        "correo": correo,
        "telefono_e164": telefono,
        "company_name": payload.company_name or prospecto.get("nombre_comercial") or prospecto.get("segmento"),
        "notes": payload.notas or prospecto.get("notas"),
        "origen": "prospeccion",
    }
    contacto_datos = {
        "prospecto_id": str(prospecto_id),
        "prospeccion_fuente": source_label,
    }
    if canal_origen != "otro":
        contacto_datos["prospeccion_canal"] = canal_origen
    contacto_body["contacto_datos"] = {k: v for k, v in contacto_datos.items() if v}
    contacto_body = {k: v for k, v in contacto_body.items() if v}

    try:
        contacto = await repo.create_contact(
            organizacion_id=organizacion_id,
            payload=contacto_body,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    metadata = _ensure_dict(prospecto.get("metadata"), default={})
    contacto_id = contacto.get("id")
    if contacto_id:
        metadata["convertido_contacto_id"] = str(contacto_id)
    metadata["convertido_en"] = datetime.now(timezone.utc).isoformat()
    metadata["recontact_blocked"] = True
    metadata["recontact_block_reason"] = "convertido_contacto"
    metadata["recontact_blocked_en"] = datetime.now(timezone.utc).isoformat()
    if canal_origen and canal_origen != "otro":
        metadata["ultimo_canal_prospeccion"] = canal_origen
    if payload.stage:
        metadata["stage"] = payload.stage
    elif not metadata.get("stage"):
        metadata["stage"] = "evaluate"

    oportunidad = None
    oportunidad_id: UUID | None = None
    try:
        stage_payload = await repo.get_stage_by_code(
            organizacion_id=organizacion_id,
            codigo="prospeccion_primer_contacto",
        )
        if not stage_payload:
            stage_payload = await repo.ensure_prospeccion_stage(
                organizacion_id=organizacion_id,
            )
    except CRMRepositoryError as exc:
        logger.warning("prospeccion.stage_lookup_failed", extra={"error": str(exc)})
        stage_payload = None

    try:
        stage_id = (
            _safe_uuid(stage_payload.get("id")) if stage_payload else None
        )
    except Exception:
        stage_id = None

    if stage_id is None:
        try:
            stage_id = await repo.get_default_stage_id(organizacion_id=organizacion_id)
        except CRMRepositoryError as exc:  # pragma: no cover - fallback improbable
            logger.warning("prospeccion.stage_default_failed", extra={"error": str(exc)})
            stage_id = None

    if stage_id and contacto_id:
        opportunity_title = nombre or prospecto.get("nombre_comercial") or prospecto.get("display_name") or "Prospección"
        opportunity_metadata = {
            "prospecto_id": str(prospecto_id),
            "source": source_label,
        }
        if canal_origen != "otro":
            opportunity_metadata["prospeccion_canal"] = canal_origen
        fuente_busqueda = _clean_text(prospecto.get("fuente_busqueda"))
        if fuente_busqueda:
            opportunity_metadata["prospeccion_fuente_codigo"] = fuente_busqueda
        opportunity_metadata["canal"] = pipeline_canal_label

        opportunity_payload = {
            "contacto_principal_id": contacto_id,
            "etapa_id": str(stage_id),
            "titulo": opportunity_title[:255],
            "descripcion": payload.notas or prospecto.get("notas"),
            "metadata": opportunity_metadata,
        }
        try:
            oportunidad = await repo.create_opportunity(
                organizacion_id=organizacion_id,
                payload=opportunity_payload,
            )
        except CRMRepositoryError as exc:
            logger.warning("prospeccion.crear_oportunidad_error", extra={"error": str(exc)})
            oportunidad = None
        else:
            oportunidad_id = _safe_uuid(oportunidad.get("id"))
            if oportunidad_id:
                history_payload: dict[str, str] = {
                    "oportunidad_id": str(oportunidad_id),
                    "etapa_destino_id": str(stage_id),
                    "fuente": "prospeccion",
                }
                if usuario_id:
                    history_payload["cambiado_por_usuario_id"] = str(usuario_id)
                try:
                    await repo.append_stage_history(
                        organizacion_id=organizacion_id,
                        payload=history_payload,
                    )
                except CRMRepositoryError as exc:  # pragma: no cover - no frena flujo
                    logger.warning("prospeccion.historial_stage_error", extra={"error": str(exc)})

    if oportunidad_id:
        metadata["crm_oportunidad_id"] = str(oportunidad_id)
        metadata["crm_origen_etapa"] = "prospeccion_primer_contacto"

    try:
        updated = await repo.update_prospecto(
            usuario_token=user_token,
            prospecto_id=prospecto_id,
            payload={"metadata": metadata},
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    response: dict[str, Any] = {"ok": True, "prospecto": updated, "contacto": contacto}
    if oportunidad:
        response["oportunidad"] = oportunidad
    await _publish_prospectos_ui_event(
        organizacion_id=organizacion_id,
        event_type="prospecto_converted",
        payload={
            "prospecto_id": str(prospecto_id),
            "contacto_id": str(contacto_id) if contacto_id else None,
            "oportunidad_id": str(oportunidad_id) if oportunidad_id else None,
        },
    )
    return response


@router.post("/prospeccion/prospectos")
async def guardar_prospectos(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    payload: ProspectoSeleccionPayload,
) -> dict[str, Any]:
    """Persiste IDs seleccionados de búsquedas en la tabla de prospectos."""

    try:
        contactables = await repo.list_contactables_by_ids(
            usuario_token=user_token,
            fuente=payload.fuente,
            resultado_ids=payload.resultado_ids,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not contactables:
        raise HTTPException(status_code=404, detail="resultados_not_found")

    items = [
        _build_prospecto_from_contactable(
            row,
            segmento=payload.segmento,
            extra_metadata=payload.metadata,
        )
        for row in contactables
    ]
    try:
        prospectos = await repo.upsert_prospeccion_prospectos(
            usuario_token=user_token,
            items=items,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    try:
        await repo.refresh_prospeccion_query_daily_mv()
    except CRMRepositoryError as exc:  # pragma: no cover - no bloquea guardado
        logger.warning("prospeccion.query_daily_mv_refresh_failed", extra={"error": str(exc)})
    await _clear_prospecto_queries_cache()
    await _publish_prospectos_ui_event(
        organizacion_id=organizacion_id,
        event_type="prospectos_saved",
        payload={
            "total": len(prospectos),
            "fuente": payload.fuente,
        },
    )

    return {
        "ok": True,
        "total": len(prospectos),
        "solicitados": len(payload.resultado_ids),
        "contactables_encontrados": len(contactables),
        "prospectos": prospectos,
    }


