@router.post("/prospeccion/prospectos/grupos-delete")
async def eliminar_grupos_prospectos(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    payload: ProspectoDeleteGroupsPayload,
) -> dict[str, Any]:
    """Elimina todos los prospectos pertenecientes a uno o más grupos de búsqueda."""

    deleted_ids_accum: set[UUID] = set()
    chunk_size = 200
    page_limit = 500

    for query_value in payload.query_values:
        while True:
            try:
                rows, _ = await repo.list_prospectos(
                    usuario_token=user_token,
                    organizacion_id=organizacion_id,
                    limit=page_limit,
                    offset=0,
                    metadata_queries=[query_value],
                )
            except CRMRepositoryError as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc

            ids_batch: list[UUID] = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                row_id = row.get("id")
                if row_id is None:
                    continue
                try:
                    candidate = UUID(str(row_id))
                except (TypeError, ValueError):
                    continue
                ids_batch.append(candidate)

            if not ids_batch:
                break

            for start in range(0, len(ids_batch), chunk_size):
                chunk = ids_batch[start : start + chunk_size]
                try:
                    deleted_chunk = await repo.delete_prospectos(
                        usuario_token=user_token,
                        prospecto_ids=chunk,
                    )
                except CRMRepositoryError as exc:
                    raise HTTPException(status_code=502, detail=str(exc)) from exc
                deleted_ids_accum.update(deleted_chunk)

            if len(ids_batch) < page_limit:
                break

    try:
        await repo.refresh_prospeccion_query_daily_mv()
    except CRMRepositoryError as exc:  # pragma: no cover - no bloquea flujo principal
        logger.warning("prospeccion.query_daily_mv_refresh_failed", extra={"error": str(exc)})
    await _clear_prospecto_queries_cache()
    await _publish_prospectos_ui_event(
        organizacion_id=organizacion_id,
        event_type="prospectos_groups_deleted",
        payload={
            "total": len(deleted_ids_accum),
            "groups": payload.query_values,
        },
    )
    return {
        "ok": True,
        "total": len(deleted_ids_accum),
        "prospecto_ids": [str(value) for value in sorted(deleted_ids_accum, key=str)],
        "query_values": payload.query_values,
    }


@router.post("/prospeccion/prospectos/verificar-telefonos")
async def verificar_prospectos(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    payload: ProspectoLookupPayload,
) -> dict[str, Any]:
    """Verifica los teléfonos de prospectos con proveedor configurable."""

    tenant_organizacion_id: UUID | None = None
    user_sub = _jwt_verify_and_sub(user_token)
    if user_sub:
        try:
            user_uuid = UUID(user_sub)
        except (TypeError, ValueError):
            user_uuid = None
        if user_uuid:
            tenant_organizacion_id = await repo.get_usuario_organizacion_id(usuario_id=user_uuid)

    twilio_runtime = None
    if payload.proveedor == "twilio":
        twilio_runtime = await tenant_runtime.get_twilio_runtime_settings(
            organizacion_id=tenant_organizacion_id
        )
        if not twilio_runtime.account_sid or not twilio_runtime.auth_token:
            logger.warning(
                "twilio.not_configured",
                extra={
                    "user_sub_present": bool(user_sub),
                    "organizacion_id": str(tenant_organizacion_id) if tenant_organizacion_id else None,
                    "settings_account_sid_present": bool(settings.twilio_account_sid),
                    "settings_auth_token_present": bool(settings.twilio_auth_token),
                },
            )
            raise HTTPException(status_code=503, detail="twilio_not_configured")
        logger.info(
            "twilio.config_resolved",
            extra={
                "user_sub_present": bool(user_sub),
                "organizacion_id": str(tenant_organizacion_id) if tenant_organizacion_id else None,
                "account_sid_prefix": (twilio_runtime.account_sid or "")[:6],
                "auth_token_len": len(twilio_runtime.auth_token or ""),
                "source": "org_secret" if tenant_organizacion_id else "settings_or_global",
            },
        )

    try:
        prospectos = await repo.list_prospectos_by_ids(
            usuario_token=user_token,
            prospecto_ids=payload.prospecto_ids,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not prospectos:
        raise HTTPException(status_code=404, detail="prospectos_not_found")

    try:
        processed = await _run_prospecto_lookup(
            repo=repo,
            user_token=user_token,
            prospectos=prospectos,
            country_code=payload.country_code,
            reintentar=payload.reintentar,
            proveedor=payload.proveedor,
            twilio_account_sid=(twilio_runtime.account_sid if twilio_runtime else None),
            twilio_auth_token=(twilio_runtime.auth_token if twilio_runtime else None),
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    await _publish_prospectos_ui_event(
        organizacion_id=organizacion_id,
        event_type="prospectos_lookup_updated",
        payload={"procesados": len(processed)},
    )

    return {"ok": True, "procesados": len(processed), "detalles": processed}


