@router.post("/prospeccion/prospectos/checklist/scraper")
async def prospeccion_checklist_scraper(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    organizacion_id: UUID = Depends(require_organizacion_id),
    payload: ProspectoChecklistScraperPayload,
) -> dict[str, Any]:
    """Dispara jobs del buscador web para prospectos sin correo pero con sitio web."""

    defer_scraper, defer_details = await should_defer_non_critical_jobs(job_name="prospectos_checklist_scraper")
    if defer_scraper:
        backlog = defer_details.get("backlog")
        threshold = defer_details.get("threshold")
        reason = str(defer_details.get("reason") or "high_load")
        extra_hint = ""
        if isinstance(backlog, int) and isinstance(threshold, int):
            extra_hint = f" (backlog {backlog}/{threshold})"
        raise HTTPException(
            status_code=429,
            detail=(
                "El servidor está en alta carga y el scraper se difirió para proteger WhatsApp e Inbox. "
                f"Intenta nuevamente en 2-5 minutos{extra_hint}. Motivo: {reason}."
            ),
        )

    candidatos: list[dict[str, Any]] = []
    if payload.prospecto_ids:
        try:
            candidatos = await repo.list_prospectos_by_ids(
                usuario_token=user_token,
                prospecto_ids=payload.prospecto_ids,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
    else:
        fetch_limit = max(payload.limit * 3, payload.limit)
        try:
            candidatos = await repo.list_scraper_pending_prospectos(
                usuario_token=user_token,
                limit=fetch_limit,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc

    jobs: list[BuscadorJobResponse] = []
    seen_hosts: set[str] = set()
    job_cap = payload.limit if payload.limit else 1
    safe_max_pages = max(10, min(payload.max_pages, int(settings.checklist_scraper_max_pages)))
    safe_max_depth = max(1, min(payload.max_depth, int(settings.checklist_scraper_max_depth)))
    payload_runtime = payload.max_runtime if payload.max_runtime is not None else int(settings.checklist_scraper_max_runtime)
    safe_max_runtime = max(60, min(int(payload_runtime), int(settings.checklist_scraper_max_runtime)))
    safe_max_workers = max(1, min(int(settings.checklist_scraper_max_workers), 5))

    for candidato in candidatos:
        if len(jobs) >= job_cap:
            break
        target = _normalize_scraper_target(candidato.get("website"))
        if not target:
            continue
        url, host = target
        if host in seen_hosts:
            continue
        seen_hosts.add(host)

        params = BuscadorParams(
            sitio="domain",
            url=url,
            mode=payload.mode,
            max_pages=safe_max_pages,
            max_depth=safe_max_depth,
            max_workers=safe_max_workers,
            max_runtime=safe_max_runtime,
        )

        metadata = {
            "prospecto_id": str(candidato.get("id")),
            "fuente": "checklist_scraper",
        }
        segmento = _clean_text(candidato.get("segmento"))
        if segmento:
            metadata["segmento"] = segmento

        job_payload: dict[str, Any] = {
            "status": "pending",
            "params": _params_to_dict(params),
            "metadata": metadata,
        }
        if usuario_id:
            job_payload["creado_por"] = str(usuario_id)

        try:
            job_row = await repo.create_buscador_job(organizacion_id=organizacion_id, payload=job_payload)
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc

        BUSCADOR_JOB_MANAGER.schedule_job(repo=repo, job_row=job_row, params=params)
        jobs.append(_job_row_to_response(job_row))

    await _publish_prospectos_ui_event(
        organizacion_id=organizacion_id,
        event_type="prospectos_checklist_scraper_scheduled",
        payload={"programados": len(jobs)},
    )

    return {"ok": True, "jobs": jobs, "programados": len(jobs)}


@router.post("/prospeccion/prospectos/contactar")
async def contactar_prospectos(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    organizacion_id: UUID = Depends(require_organizacion_id),
    payload: ProspectoContactarPayload,
) -> dict[str, Any]:
    """Envía correos, WhatsApps o llamadas registrando lotes y envíos individuales."""

    if payload.campana_id is None:
        raise HTTPException(status_code=400, detail="campana_id_required")
    if not payload.canales:
        raise HTTPException(status_code=400, detail="contact_templates_required")
    for channel in payload.canales:
        if channel.template_id is None:
            raise HTTPException(status_code=400, detail=f"contact_template_required:{channel.canal}")

    template_map: dict[str, dict[str, Any]] = {}
    if payload.canales:
        template_ids = {config.template_id for config in payload.canales if config.template_id}
        if template_ids:
            try:
                template_map = await _fetch_contact_templates(
                    repo=repo,
                    user_token=user_token,
                    template_ids=template_ids,
                )
            except CRMRepositoryError as exc:
                raise HTTPException(status_code=502, detail=str(exc)) from exc
            campana_key = str(payload.campana_id)
            for template_id, template in template_map.items():
                metadata = template.get("metadata") if isinstance(template.get("metadata"), dict) else {}
                template_campana = _clean_text(metadata.get("campana_id"))
                if not template_campana:
                    raise HTTPException(
                        status_code=400,
                        detail=f"contact_template_campaign_missing:{template_id}",
                    )
                if template_campana != campana_key:
                    raise HTTPException(
                        status_code=400,
                        detail=f"contact_template_campaign_mismatch:{template_id}",
                    )

    canales_config, programacion = _resolve_contact_channels(
        payload,
        template_map=template_map,
    )
    programacion = await _align_programacion_with_active_campaign_schedule(
        repo=repo,
        user_token=user_token,
        campana_id=payload.campana_id,
        canales=set(canales_config.keys()),
        programacion=programacion,
        separacion_segundos=payload.separacion_segundos,
    )
    await _apply_default_whatsapp_runtime_template(
        canales_config=canales_config,
        organizacion_id=organizacion_id,
    )
    _assert_whatsapp_template_configured(canales_config)
    if not canales_config:
        raise HTTPException(status_code=400, detail="contact_channels_required")

    selector_filtros: dict[str, Any] = {}
    metadata_extra: dict[str, Any] = {"canales_config": canales_config}
    if programacion:
        metadata_extra["programacion"] = programacion

    filtros_fuente: ProspectoFiltroPayload | None = None
    lista_nombre: str | None = None
    omitidos: list[dict[str, Any]] = []
    if payload.lista_id:
        try:
            lista_row = await _retry_transient_repo_error(
                operation="get_contact_list",
                func=lambda: repo.get_contact_list(usuario_token=user_token, lista_id=payload.lista_id),
                retries=1,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not lista_row:
            raise HTTPException(status_code=404, detail="contact_list_not_found")
        filtros_data = _ensure_dict(lista_row.get("filtros"), default={})
        try:
            filtros_fuente = ProspectoFiltroPayload.model_validate(filtros_data)
        except Exception as exc:  # noqa: BLE001
            logger.warning("Lista con filtros inválidos %s: %s", payload.lista_id, exc)
            raise HTTPException(status_code=400, detail="contact_list_invalid_filters") from exc
        selector_filtros = filtros_data
        lista_nombre = _clean_text(lista_row.get("nombre"))
        if lista_nombre:
            metadata_extra["lista_nombre"] = lista_nombre
    elif payload.filtros:
        filtros_fuente = payload.filtros
        selector_filtros = payload.filtros.model_dump(exclude_none=True)

    prospectos: list[dict[str, Any]] = []
    total_prospectos = 0

    if payload.prospecto_ids:
        try:
            prospectos = await _retry_transient_repo_error(
                operation="list_prospectos_by_ids",
                func=lambda: repo.list_prospectos_by_ids(
                    usuario_token=user_token,
                    prospecto_ids=payload.prospecto_ids,
                ),
                retries=1,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not prospectos:
            raise HTTPException(status_code=404, detail="prospectos_not_found")
        total_prospectos = len(prospectos)
        selector_filtros = selector_filtros or {"prospecto_ids": [str(value) for value in payload.prospecto_ids]}
    else:
        if not filtros_fuente:
            raise HTTPException(status_code=400, detail="prospecto_selector_required")
        try:
            repo_kwargs = _prospecto_filters_to_kwargs(filtros_fuente)
            prospectos, total = await _retry_transient_repo_error(
                operation="list_prospectos_for_contactar",
                func=lambda: repo.list_prospectos(
                    usuario_token=user_token,
                    organizacion_id=organizacion_id,
                    limit=MAX_PROSPECCION_BATCH,
                    offset=0,
                    order="creado_en.desc",
                    **repo_kwargs,
                ),
                retries=1,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
        if not prospectos:
            raise HTTPException(status_code=404, detail="prospectos_not_found")
        if total > MAX_PROSPECCION_BATCH:
            raise HTTPException(status_code=400, detail="prospecto_batch_limit_exceeded")
        total_prospectos = total
        selector_filtros = selector_filtros or filtros_fuente.model_dump(exclude_none=True)

    prospectos, bloqueados = _split_recontact_blocked_prospectos(prospectos)
    if not prospectos:
        raise HTTPException(status_code=400, detail="prospectos_recontact_blocked")
    total_prospectos = len(prospectos)
    if bloqueados:
        omitidos.append(
            {
                "motivo": "convertido_contacto",
                "prospecto_ids": bloqueados,
                "total": len(bloqueados),
            }
        )
        metadata_extra["recontacto_bloqueados"] = {"total": len(bloqueados)}

    prospecto_uuid_ids: list[UUID] = []
    for item in prospectos:
        raw_id = item.get("id") or item.get("prospecto_id")
        try:
            if raw_id:
                prospecto_uuid_ids.append(UUID(str(raw_id)))
        except (TypeError, ValueError):
            continue
    try:
        suppressions = await _retry_transient_repo_error(
            operation="list_active_contact_suppressions_for_prospectos",
            func=lambda: repo.list_active_contact_suppressions_for_prospectos(
                usuario_token=user_token,
                prospecto_ids=prospecto_uuid_ids,
                canales=list(canales_config.keys()),
            ),
            retries=1,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    suppression_map = _build_suppression_channel_map(suppressions)
    prospectos = _attach_suppressions_to_prospectos(prospectos, suppression_map)
    preview_entries, _preview_suppressed = _build_contact_envios_entries(
        batch_id="preview",
        prospectos=prospectos,
        canales=canales_config,
        programacion=programacion,
        separacion_segundos=payload.separacion_segundos,
    )
    projected_email_by_utc_day: dict[date, int] = {}
    for entry in preview_entries:
        if _clean_text(entry.get("canal")) != "correo":
            continue
        programmed = _parse_iso_datetime(entry.get("programado_en"))
        if programmed is None:
            programmed = datetime.now(timezone.utc)
        if programmed.tzinfo is None:
            programmed = programmed.replace(tzinfo=timezone.utc)
        quota_day_utc = programmed.astimezone(timezone.utc).date()
        projected_email_by_utc_day[quota_day_utc] = projected_email_by_utc_day.get(quota_day_utc, 0) + 1

    if projected_email_by_utc_day:
        brevo_settings = await tenant_runtime.get_brevo_runtime_settings(organizacion_id=organizacion_id)
        api_key = _clean_text(brevo_settings.api_key)
        if api_key:
            for quota_day_utc, projected_email_sends in sorted(projected_email_by_utc_day.items()):
                day_start_utc = datetime.combine(quota_day_utc, datetime.min.time(), tzinfo=timezone.utc)
                day_end_utc_exclusive = day_start_utc + timedelta(days=1)
                scheduled_for_day = 0
                try:
                    scheduled_for_day = await _retry_transient_repo_error(
                        operation="count_pending_email_envios_for_local_day",
                        func=lambda day_start_utc=day_start_utc, day_end_utc_exclusive=day_end_utc_exclusive: repo.count_pending_email_envios_for_local_day(
                            usuario_token=user_token,
                            start_utc=day_start_utc,
                            end_utc_exclusive=day_end_utc_exclusive,
                        ),
                        retries=1,
                    )
                except CRMRepositoryError as exc:
                    logger.warning(
                        "prospeccion.contactar.scheduled_count_failed",
                        extra={"error": str(exc), "quota_day_utc": quota_day_utc.isoformat()},
                    )
                try:
                    quota = await fetch_brevo_daily_quota(
                        api_key=api_key,
                        base_url=brevo_settings.base_url,
                        local_day=quota_day_utc,
                    )
                except Exception as exc:  # noqa: BLE001
                    logger.warning(
                        "prospeccion.contactar.brevo_quota_check_failed",
                        extra={"error": str(exc), "quota_day_utc": quota_day_utc.isoformat()},
                    )
                    continue
                remaining_for_new = quota.remaining
                if remaining_for_new is not None:
                    remaining_for_new = max(remaining_for_new - scheduled_for_day, 0)
                if remaining_for_new is not None and remaining_for_new < projected_email_sends:
                    raise HTTPException(
                        status_code=400,
                        detail=(
                            "brevo_daily_quota_exceeded:"
                            f"{remaining_for_new}:{projected_email_sends}:{quota_day_utc.isoformat()}"
                        ),
                    )

    try:
        batch = await _retry_transient_repo_error(
            operation="create_contact_batch",
            func=lambda: repo.create_contact_batch(
                usuario_token=user_token,
                payload=_build_contact_batch_payload(
                    canales=list(canales_config.keys()),
                    total=total_prospectos,
                    payload=payload,
                    usuario_id=usuario_id,
                    filtros=selector_filtros,
                    programacion=programacion,
                    metadata_extra=metadata_extra,
                ),
            ),
            retries=1,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    batch_id = batch.get("id")
    if not batch_id:
        raise HTTPException(status_code=502, detail="contact_batch_invalid")

    envios_entries, suppressed_by_channel = _build_contact_envios_entries(
        batch_id=batch_id,
        prospectos=prospectos,
        canales=canales_config,
        programacion=programacion,
        separacion_segundos=payload.separacion_segundos,
    )
    if suppressed_by_channel:
        for canal, ids in suppressed_by_channel.items():
            omitidos.append(
                {
                    "motivo": f"opt_out_{canal}",
                    "prospecto_ids": ids,
                    "total": len(ids),
                }
            )
        batch_meta = _ensure_dict(batch.get("metadata"), default={})
        batch_meta["suppressions_bloqueados"] = {
            canal: len(ids) for canal, ids in suppressed_by_channel.items()
        }
        try:
            await _retry_transient_repo_error(
                operation="update_contact_batch",
                func=lambda: repo.update_contact_batch(
                    usuario_token=user_token,
                    batch_id=UUID(str(batch_id)),
                    payload={"metadata": batch_meta},
                ),
                retries=1,
            )
        except CRMRepositoryError as exc:
            raise HTTPException(status_code=502, detail=str(exc)) from exc
    try:
        envios = await _retry_transient_repo_error(
            operation="insert_contact_envios",
            func=lambda: repo.insert_contact_envios(
                usuario_token=user_token,
                entries=envios_entries,
            ),
            retries=1,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    resumen = _build_contact_resumen(envios)
    contact_sender.notify_new_envios()
    await _publish_prospectos_ui_event(
        organizacion_id=organizacion_id,
        event_type="prospectos_contact_batch_created",
        payload={
            "batch_id": str(batch_id),
            "envios": len(envios),
            "prospectos": total_prospectos,
        },
    )

    response: dict[str, Any] = {"ok": True, "batch_id": str(batch_id), "contactos": resumen}
    if omitidos:
        response["omitidos"] = omitidos
    return response


@router.get("/prospeccion/contacto/batches/{batch_id}")
async def obtener_contacto_batch(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    batch_id: UUID,
) -> dict[str, Any]:
    """Devuelve un lote específico con resumen de sus envíos."""

    try:
        batch = await _retry_transient_repo_error(
            operation="get_contact_batch",
            func=lambda: repo.get_contact_batch(usuario_token=user_token, batch_id=batch_id),
            retries=1,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    if not batch:
        raise HTTPException(status_code=404, detail="contact_batch_not_found")

    try:
        resumen_rows = await _retry_transient_repo_error(
            operation="summarize_contact_batch",
            func=lambda: repo.summarize_contact_batch(usuario_token=user_token, batch_id=batch_id),
            retries=1,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    totales: dict[str, int] = {}
    total_envios = 0
    for row in resumen_rows:
        estado_key = _clean_text(row.get("estado")) or "desconocido"
        count_value = row.get("count") if isinstance(row, dict) else None
        try:
            count_int = int(count_value)
        except (TypeError, ValueError):
            count_int = 0
        totales[estado_key] = count_int
        total_envios += count_int

    return {
        "ok": True,
        "batch": batch,
        "totales": totales,
        "total_envios": total_envios,
    }


@router.post("/prospeccion/contacto/envios/{envio_id}/reintentar")
async def reintentar_contacto_envio(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    envio_id: UUID,
) -> dict[str, Any]:
    """Reprograma un envío fallido/omitido para que el worker lo procese nuevamente."""

    envio = await repo.get_contact_envio(usuario_token=user_token, envio_id=envio_id)
    if not envio:
        raise HTTPException(status_code=404, detail="contact_envio_not_found")
    estado_actual = _clean_text(envio.get("estado")) or ""
    if estado_actual in {"pendiente", "procesando"}:
        raise HTTPException(status_code=400, detail="contact_envio_busy")

    reprogramado_en = datetime.now(timezone.utc).isoformat()
    payload = {
        "estado": "pendiente",
        "intento_actual": 0,
        "error": None,
        "procesado_en": None,
        "programado_en": reprogramado_en,
    }
    updated = await repo.update_contact_envio(
        usuario_token=user_token,
        envio_id=envio_id,
        payload=payload,
    )

    log_entry = _build_contact_log_entry(
        prospecto_id=envio.get("prospecto_id"),
        canal=str(envio.get("canal")),
        estado="pendiente",
        detalle={
            "action": "manual_retry",
            "previous_estado": estado_actual,
        },
        batch_id=envio.get("batch_id"),
        envio_id=envio_id,
    )
    await repo.insert_prospecto_logs(usuario_token=user_token, entries=[log_entry])
    contact_sender.notify_new_envios()
    batch_id_value = envio.get("batch_id")
    if batch_id_value:
        await progress_hub.publish(
            str(batch_id_value),
            {
                "type": "envio",
                "batch_id": batch_id_value,
                "envio_id": str(envio_id),
                "estado": "pendiente",
            },
        )

    return {"ok": True, "envio": updated}


@router.post("/prospeccion/contacto/envios/{envio_id}/cancelar")
async def cancelar_contacto_envio(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    envio_id: UUID,
) -> dict[str, Any]:
    """Cancela manualmente un envío pendiente/procesando."""

    envio = await repo.get_contact_envio(usuario_token=user_token, envio_id=envio_id)
    if not envio:
        raise HTTPException(status_code=404, detail="contact_envio_not_found")
    estado_actual = (_clean_text(envio.get("estado")) or "").lower()
    if estado_actual not in {"pendiente", "procesando"}:
        raise HTTPException(status_code=400, detail="contact_envio_not_cancellable")

    motivo = "cancelado_manual"
    now_iso = datetime.now(timezone.utc).isoformat()
    payload = {
        "estado": "cancelado",
        "error": motivo,
        "procesado_en": now_iso,
    }
    updated = await repo.update_contact_envio(
        usuario_token=user_token,
        envio_id=envio_id,
        payload=payload,
    )

    log_entry = _build_contact_log_entry(
        prospecto_id=envio.get("prospecto_id"),
        canal=_clean_text(envio.get("canal")) or "canal",
        estado="cancelado",
        detalle={
            "action": "manual_cancel",
            "previous_estado": estado_actual,
            "reason": motivo,
        },
        error=motivo,
        batch_id=envio.get("batch_id"),
        envio_id=envio_id,
    )
    await repo.insert_prospecto_logs(usuario_token=user_token, entries=[log_entry])

    batch_id_value = envio.get("batch_id")
    if batch_id_value:
        await progress_hub.publish(
            str(batch_id_value),
            {
                "type": "envio",
                "batch_id": batch_id_value,
                "envio_id": str(envio_id),
                "estado": "cancelado",
            },
        )

    return {"ok": True, "envio": updated}


@router.get("/prospeccion/contacto/batches/{batch_id}/stream")
async def stream_contacto_batch(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    batch_id: UUID,
) -> StreamingResponse:
    """Stream SSE con actualizaciones del lote."""

    batch = await repo.get_contact_batch(usuario_token=user_token, batch_id=batch_id)
    if not batch:
        raise HTTPException(status_code=404, detail="contact_batch_not_found")

    queue = await progress_hub.subscribe(str(batch_id))

    async def event_generator() -> Any:
        try:
            yield _sse_payload({"type": "connected", "batch_id": str(batch_id)})
            while True:
                try:
                    event = await asyncio.wait_for(queue.get(), timeout=30)
                except asyncio.TimeoutError:
                    yield _sse_payload({"type": "ping"})
                    continue
                yield _sse_payload(event)
        finally:
            await progress_hub.unsubscribe(str(batch_id), queue)

    headers = {
        "Cache-Control": "no-cache",
        "Content-Type": "text/event-stream",
        "Connection": "keep-alive",
    }
    return StreamingResponse(event_generator(), media_type="text/event-stream", headers=headers)


@router.post("/prospeccion/contacto/batches/{batch_id}/cancelar")
async def cancelar_contacto_batch(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    batch_id: UUID,
) -> dict[str, Any]:
    """Cancela un lote y los envíos pendientes."""

    batch = await repo.get_contact_batch(usuario_token=user_token, batch_id=batch_id)
    if not batch:
        raise HTTPException(status_code=404, detail="contact_batch_not_found")
    estado_actual = _clean_text(batch.get("estado")) or ""
    if estado_actual in {"completado", "cancelado"}:
        raise HTTPException(status_code=400, detail="contact_batch_not_cancellable")

    motivo = "cancelado_manual"
    cancelled_envios = await repo.cancel_pending_envios(
        usuario_token=user_token,
        batch_id=batch_id,
        motivo=motivo,
    )

    now_iso = datetime.now(timezone.utc).isoformat()
    updated_batch = await repo.update_contact_batch(
        usuario_token=user_token,
        batch_id=batch_id,
        payload={"estado": "cancelado", "finalizado_en": now_iso},
    )

    if cancelled_envios:
        logs = [
            _build_contact_log_entry(
                prospecto_id=envio.get("prospecto_id"),
                canal=_clean_text(envio.get("canal")) or "canal",
                estado="cancelado",
                detalle={"reason": motivo},
                error=motivo,
                batch_id=batch_id,
                envio_id=envio.get("id"),
            )
            for envio in cancelled_envios
        ]
        await repo.insert_prospecto_logs(usuario_token=user_token, entries=logs)
        for envio in cancelled_envios:
            await progress_hub.publish(
                str(batch_id),
                {
                    "type": "envio",
                    "batch_id": str(batch_id),
                    "envio_id": envio.get("id"),
                    "estado": "cancelado",
                },
            )

    await progress_hub.publish(
        str(batch_id),
        {
            "type": "batch",
            "batch_id": str(batch_id),
            "estado": "cancelado",
        },
    )

    return {
        "ok": True,
        "batch": updated_batch,
        "envios_cancelados": len(cancelled_envios),
    }


@router.get("/prospeccion/contacto/metrics")
async def obtener_metrics_contacto(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("reports.view")),
    user_token: str = Depends(require_user_token),
) -> dict[str, Any]:
    """Snapshot simple de envíos por canal y estado."""

    snapshot = contact_metrics.snapshot()
    transformado = {
        canal: {"totales": sum(counter.values()), "por_estado": dict(counter)}
        for canal, counter in snapshot.por_canal.items()
    }
    conversion_rows: list[dict[str, Any]] = []
    try:
        conversion_rows = await repo.get_prospeccion_conversion_fuente(usuario_token=user_token)
    except CRMRepositoryError as exc:
        logger.warning("prospeccion.metrics.conversion_fuente_failed", extra={"error": str(exc)})
    brevo_rows: list[dict[str, Any]] = []
    try:
        brevo_rows = await repo.get_prospeccion_brevo_eventos_resumen(usuario_token=user_token)
    except CRMRepositoryError as exc:
        logger.warning("prospeccion.metrics.brevo_eventos_failed", extra={"error": str(exc)})

    conversion_por_fuente: list[dict[str, Any]] = []
    for row in conversion_rows:
        fuente = _clean_text(row.get("fuente")) or "desconocido"
        conversion_por_fuente.append(
            {
                "fuente": fuente,
                "total_prospectos": int(row.get("total_prospectos") or 0),
                "prospectos_contactados": int(row.get("prospectos_contactados") or 0),
                "envios_totales": int(row.get("envios_totales") or 0),
                "envios_enviados": int(row.get("envios_enviados") or 0),
                "prospectos_convertidos": int(row.get("prospectos_convertidos") or 0),
                "conversion_contacto_pct": float(row.get("conversion_contacto_pct") or 0),
                "conversion_convertido_pct": float(row.get("conversion_convertido_pct") or 0),
            }
        )

    brevo_eventos: list[dict[str, Any]] = []
    for row in brevo_rows:
        evento = _clean_text(row.get("evento"))
        if not evento:
            continue
        brevo_eventos.append(
            {
                "evento": evento,
                "total": int(row.get("total") or 0),
                "ultimo_evento_en": row.get("ultimo_evento_en"),
            }
        )

    return {
        "ok": True,
        "canales": transformado,
        "conversion_por_fuente": conversion_por_fuente,
        "brevo_eventos": brevo_eventos,
    }


@router.get("/prospeccion/contacto/brevo-quota")
async def obtener_brevo_quota_diaria(
    *,
    repo: CRMRepository = Depends(get_repository),
    _: str = Depends(require_permission("ejecutar_busquedas")),
    user_token: str = Depends(require_user_token),
    organizacion_id: UUID = Depends(require_organizacion_id),
    usuario_id: UUID | None = Depends(optional_usuario_id),
) -> dict[str, Any]:
    """Devuelve consumo diario de Brevo y cuota estimada disponible."""

    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    zoneinfo = ZoneInfo(effective_timezone)
    local_day = datetime.now(zoneinfo).date()
    # Brevo aggregatedReport opera por día UTC; usamos el mismo corte para evitar desalineación.
    brevo_day_utc = datetime.now(timezone.utc).date()
    day_start_utc = datetime.combine(brevo_day_utc, datetime.min.time(), tzinfo=timezone.utc)
    day_end_utc_exclusive = day_start_utc + timedelta(days=1)
    scheduled_today = 0
    try:
        scheduled_today = await repo.count_pending_email_envios_for_local_day(
            usuario_token=user_token,
            start_utc=day_start_utc,
            end_utc_exclusive=day_end_utc_exclusive,
        )
    except CRMRepositoryError as exc:
        logger.warning(
            "prospeccion.brevo_quota_scheduled_count_failed",
            extra={"error": str(exc)},
        )
    brevo_settings = await tenant_runtime.get_brevo_runtime_settings(organizacion_id=organizacion_id)
    api_key = _clean_text(brevo_settings.api_key)
    if not api_key:
        return {
            "ok": True,
            "configured": False,
            "available": False,
            "timezone": effective_timezone,
            "date_local": local_day.isoformat(),
            "date_brevo_utc": brevo_day_utc.isoformat(),
            "sent_today": None,
            "scheduled_today": scheduled_today,
            "projected_today": None,
            "daily_limit": None,
            "remaining": None,
            "remaining_after_scheduled": None,
            "usage_pct": None,
            "plan_type": None,
            "plan_credits": None,
            "warnings": ["brevo_not_configured"],
        }
    try:
        snapshot = await fetch_brevo_daily_quota(
            api_key=api_key,
            base_url=brevo_settings.base_url,
            local_day=brevo_day_utc,
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("prospeccion.brevo_quota_failed", extra={"error": str(exc)})
        return {
            "ok": True,
            "configured": True,
            "available": False,
            "timezone": effective_timezone,
            "date_local": local_day.isoformat(),
            "date_brevo_utc": brevo_day_utc.isoformat(),
            "sent_today": None,
            "scheduled_today": scheduled_today,
            "projected_today": None,
            "daily_limit": None,
            "remaining": None,
            "remaining_after_scheduled": None,
            "usage_pct": None,
            "plan_type": None,
            "plan_credits": None,
            "warnings": ["brevo_quota_unavailable"],
        }
    projected_today: int | None = None
    remaining_after_scheduled: int | None = None
    if snapshot.sent_today is not None:
        projected_today = snapshot.sent_today + scheduled_today
    if snapshot.remaining is not None:
        remaining_after_scheduled = max(snapshot.remaining - scheduled_today, 0)
    return {
        "ok": True,
        "configured": True,
        "available": True,
        "timezone": effective_timezone,
        "date_local": local_day.isoformat(),
        "date_brevo_utc": brevo_day_utc.isoformat(),
        "sent_today": snapshot.sent_today,
        "scheduled_today": scheduled_today,
        "projected_today": projected_today,
        "daily_limit": snapshot.daily_limit,
        "remaining": snapshot.remaining,
        "remaining_after_scheduled": remaining_after_scheduled,
        "usage_pct": snapshot.usage_pct,
        "plan_type": snapshot.plan_type,
        "plan_credits": snapshot.plan_credits,
        "warnings": snapshot.warnings,
    }


@router.post("/prospeccion/contacto/brevo/webhook", include_in_schema=False)
async def prospeccion_contacto_brevo_webhook(
    *,
    repo: CRMRepository = Depends(get_repository),
    background_tasks: BackgroundTasks,
    mode: Annotated[Literal["async", "sync"], Query()] = "async",
    payload: Any = Body(...),
) -> dict[str, Any]:
    """Recibe eventos desde Brevo y sincroniza los envíos."""

    events: list[dict[str, Any]] = []
    if isinstance(payload, list):
        events = [event for event in payload if isinstance(event, dict)]
    elif isinstance(payload, dict):
        events = [payload]
    if not events:
        raise HTTPException(status_code=400, detail="payload_invalid")

    async def _process_brevo_events_background(*, repo: CRMRepository, events: list[dict[str, Any]]) -> None:
        try:
            processed_events = await process_brevo_events(repo=repo, events=events)
            logger.info(
                "crm.prospeccion.brevo_webhook.async_processed",
                extra={"events": len(events), "processed_events": processed_events},
            )
        except Exception as exc:  # pragma: no cover - defensive logging in async background task
            logger.exception(
                "crm.prospeccion.brevo_webhook.async_failed",
                extra={"events": len(events), "error": str(exc)},
            )

    if mode == "sync":
        processed_events = await process_brevo_events(repo=repo, events=events)
        processed_inbound = 0
        return {
            "ok": True,
            "mode": mode,
            "recibidos": len(events),
            "procesados": processed_events + processed_inbound,
            "procesados_eventos": processed_events,
            "procesados_inbound": processed_inbound,
        }

    background_tasks.add_task(_process_brevo_events_background, repo=repo, events=events)
    return {
        "ok": True,
        "mode": mode,
        "recibidos": len(events),
        "procesados": 0,
        "procesados_eventos": 0,
        "procesados_inbound": 0,
    }


