@router.get(
    "/asignaciones_vendedores",
    response_model=WhatsAppSalesAssignmentsResponse,
)
async def list_sales_assignments(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_any_permission(["conv.read", "audit.view", "audit.view_all"])),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
    oportunidad_id: UUID | None = Query(default=None),
    contacto_id: UUID | None = Query(default=None),
    conversacion_id: UUID | None = Query(default=None),
    vendedor_id: UUID | None = Query(default=None),
) -> WhatsAppSalesAssignmentsResponse:
    if usuario_id is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="auth_required")
    can_view_all = await repo.current_user_has_perm(codigo="audit.view_all")
    if not can_view_all and vendedor_id:
        if not await repo.is_in_current_user_scope(usuario_id=vendedor_id):
            raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="forbidden")
    if not can_view_all:
        vendedor_id = usuario_id
    try:
        rows = await repo.list_whatsapp_sales_assignments(
            organizacion_id=organizacion_id,
            limit=limit,
            offset=offset,
            oportunidad_id=oportunidad_id,
            contacto_id=contacto_id,
            conversacion_id=conversacion_id,
            vendedor_id=vendedor_id,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    items = [WhatsAppSalesAssignment.model_validate(row) for row in rows]
    return WhatsAppSalesAssignmentsResponse(items=items, limit=limit, offset=offset)


@router.get("/pipeline/overview", response_model=CRMPipelineOverview)
async def pipeline_overview(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    user_token: str = Depends(require_user_token),  # noqa: ARG001
    usuario_id: UUID | None = Depends(optional_usuario_id),
    limit: Annotated[int, Query(ge=10, le=500)] = 200,
    days: Annotated[int, Query(ge=7, le=90)] = 30,
    rango: str | None = Query(default=None),
    desde: str | None = Query(default=None),
    hasta: str | None = Query(default=None),
) -> CRMPipelineOverview:
    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    created_from: datetime | None = None
    created_to: datetime | None = None
    days_range = days
    if rango or desde or hasta:
        created_from, created_to = _resolve_date_range(
            rango,
            desde,
            hasta,
            timezone_name=effective_timezone,
        )
        zone = ZoneInfo((effective_timezone or "UTC").strip() or "UTC")
        range_end = (created_to or datetime.now(timezone.utc)).astimezone(zone).date()
        range_start = (created_from or _resolve_recent_days_created_from_utc(
            days=days,
            timezone_name=effective_timezone,
        )).astimezone(zone).date()
        days_range = max(1, (range_end - range_start).days + 1)
    else:
        created_from = _resolve_recent_days_created_from_utc(
            days=days,
            timezone_name=effective_timezone,
        )
    fetch_limit = max(limit, 500)
    try:
        rows, total_rows = await repo.list_pipeline_opportunities(
            organizacion_id=organizacion_id,
            limit=fetch_limit,
            created_from=created_from,
            created_to=created_to,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    overview = _build_pipeline_overview(
        rows,
        total_rows,
        limit,
        days_range,
        timezone_name=effective_timezone,
    )
    return overview


@router.get("/pipeline/board", response_model=CRMPipelineBoard)
async def pipeline_board(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    user_token: str = Depends(require_user_token),
    limit: Annotated[int, Query(ge=50, le=1000)] = 400,
    tablero_id: UUID | None = Query(default=None),
    asignado_id: UUID | None = Query(default=None),
    canal: str | None = Query(default=None),
    estado: str | None = Query(default=None),
    q: str | None = Query(default=None),
    etapa_ids: str | None = Query(default=None),
    tiene_cita: str | None = Query(default=None),
) -> CRMPipelineBoard:
    """Construir el board del pipeline filtrando opcionalmente por tablero."""
    try:
        try:
            await repo.ensure_prospeccion_stage(organizacion_id=organizacion_id)
        except CRMRepositoryError as stage_exc:
            logger.warning("crm.ensure_prospeccion_stage_failed", extra={"error": str(stage_exc)})

        stages = await repo.list_pipelines(organizacion_id=organizacion_id, tablero_id=tablero_id)
        rows, _ = await repo.list_pipeline_opportunities(
            organizacion_id=organizacion_id,
            limit=limit,
            tablero_id=tablero_id,
            asignado_id=asignado_id,
            canal=canal,
            estado=estado,
            q=q,
            etapa_ids=etapa_ids,
            tiene_cita=tiene_cita,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    visitors = 0
    try:
        kpis_payload = await repo.visitas_dashboard_kpis(usuario_token=user_token)
        visitors = _extract_visitas_sin_chat(kpis_payload)
    except CRMRepositoryError:
        visitors = 0

    board = _build_pipeline_board(stages, rows, tablero_id)
    return CRMPipelineBoard(
        stages=board.stages,
        sin_conversacion=board.sin_conversacion,
        visitantes_sin_chat=visitors,
    )


@router.get("/pipeline/scoring/kpis", response_model=CRMPipelineScoringKpis)
async def pipeline_scoring_kpis(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("pipeline.view")),
    usuario_id: UUID | None = Depends(optional_usuario_id),
    days: Annotated[int, Query(ge=1, le=90)] = 7,
    limit: Annotated[int, Query(ge=100, le=5000)] = 2000,
    asignado_id: UUID | None = Query(default=None),
    canal: str | None = Query(default=None),
    estado: str | None = Query(default=None),
    q: str | None = Query(default=None),
    etapa_ids: str | None = Query(default=None),
    tiene_cita: str | None = Query(default=None),
) -> CRMPipelineScoringKpis:
    effective_timezone, _timezone_source = await _resolve_effective_timezone_name(
        repo=repo,
        organizacion_id=organizacion_id,
        usuario_id=usuario_id,
    )
    created_from = _resolve_recent_days_created_from_utc(
        days=days,
        timezone_name=effective_timezone,
    )
    # Si no se pasa asignado_id explícitamente, y el usuario es vendedor (no admin),
    # forzamos KPIs a su propio alcance para evitar que vea métricas globales
    # (los KPIs se calculan con service role para telemetría).
    if asignado_id is None:
        try:
            ctx = await repo.get_permission_context()
        except CRMRepositoryError:
            ctx = {}
        roles = ctx.get("roles")
        es_admin_value = ctx.get("es_admin")
        is_admin_ctx = bool(es_admin_value) if isinstance(es_admin_value, (bool, int)) else False
        role_values = roles if isinstance(roles, list) else []
        is_privileged_ctx = is_admin_ctx or any(
            isinstance(item, str)
            and (
                item.strip().lower() in ("admin", "0002", "supervisor")
                or "admin" in item.strip().lower()
                or "supervisor" in item.strip().lower()
            )
            for item in role_values
        )
        is_vendedor_ctx = any(
            isinstance(item, str)
            and (
                item.strip().lower() in ("0003", "agente", "vendedor")
                or "agente" in item.strip().lower()
                or "vendedor" in item.strip().lower()
            )
            for item in role_values
        )
        usuario_ctx = ctx.get("usuario_id")
        if is_vendedor_ctx and not is_privileged_ctx and usuario_ctx:
            try:
                asignado_id = UUID(str(usuario_ctx))
            except (TypeError, ValueError):
                asignado_id = None
        logger.info(
            "crm.pipeline_scoring_kpis.effective_scope",
            extra={
                "has_user_token": bool(getattr(repo, "_user_token", None)),
                "ctx_usuario_id": str(usuario_ctx) if usuario_ctx else None,
                "ctx_roles": role_values,
                "ctx_es_admin": is_admin_ctx,
                "ctx_privileged": is_privileged_ctx,
                "incoming_asignado_id": None,
                "effective_asignado_id": str(asignado_id) if asignado_id else None,
                "days": days,
                "limit": limit,
            },
        )
    else:
        logger.info(
            "crm.pipeline_scoring_kpis.effective_scope",
            extra={
                "has_user_token": bool(getattr(repo, "_user_token", None)),
                "incoming_asignado_id": str(asignado_id),
                "effective_asignado_id": str(asignado_id),
                "days": days,
                "limit": limit,
            },
        )
    try:
        rows = await repo.list_opportunity_scoring_events(
            organizacion_id=organizacion_id,
            created_from=created_from,
            limit=limit,
            asignado_id=asignado_id,
            canal=canal,
            estado=estado,
            q=q,
            etapa_ids=etapa_ids,
            tiene_cita=tiene_cita,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    logger.info(
        "crm.pipeline_scoring_kpis.rows_loaded",
        extra={
            "effective_asignado_id": str(asignado_id) if asignado_id else None,
            "rows": len(rows),
            "unique_opportunities": len({str(r.get("oportunidad_id")) for r in rows if r.get("oportunidad_id")}),
            "days": days,
        },
    )
    return _build_scoring_kpis(rows=rows, window_days=days)


@router.get("/pipeline/scoring/config", response_model=CRMScoringConfigBundle)
async def get_pipeline_scoring_config(
    *,
    repo: CRMRepository = Depends(get_repository),
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("settings.view")),
    canal: Literal["whatsapp", "webchat"] = Query(...),
    include_inactive: bool = Query(default=False),
) -> CRMScoringConfigBundle:
    if not await tenant_runtime.is_profiling_enabled(
        organizacion_id=organizacion_id,
        channel=canal,
    ):
        raise HTTPException(status_code=403, detail="profiling_disabled")
    try:
        profiles = await repo.list_scoring_profiles(
            organizacion_id=organizacion_id,
            canal=canal,
            only_active=not include_inactive,
        )
        questions = await repo.list_scoring_questions(
            organizacion_id=organizacion_id,
            canal=canal,
            include_inactive=include_inactive,
        )
        reprompts = await repo.list_scoring_question_reprompts(
            organizacion_id=organizacion_id,
            canal=canal,
            include_inactive=include_inactive,
        )
        rules = await repo.list_scoring_rules(
            organizacion_id=organizacion_id,
            canal=canal,
            include_inactive=include_inactive,
        )
    except CRMRepositoryError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc

    return _build_scoring_config_bundle(
        canal=canal,
        profile_rows=profiles,
        question_rows=questions,
        reprompt_rows=reprompts,
        rule_rows=rules,
    )


@router.get("/pipeline/scoring/feature-status", response_model=CRMScoringFeatureStatus)
async def get_pipeline_scoring_feature_status(
    *,
    organizacion_id: UUID = Depends(require_organizacion_id),
    _: str = Depends(require_permission("settings.view")),
    canal: Literal["whatsapp", "webchat"] | None = Query(default=None),
) -> CRMScoringFeatureStatus:
    global_enabled = await tenant_runtime.is_profiling_enabled(
        organizacion_id=organizacion_id,
        channel=None,
    )
    by_channel: dict[str, bool] = {}
    for channel_key in ("whatsapp", "webchat"):
        by_channel[channel_key] = await tenant_runtime.is_profiling_enabled(
            organizacion_id=organizacion_id,
            channel=channel_key,
        )
    resolved_enabled = by_channel[canal] if canal in {"whatsapp", "webchat"} else global_enabled
    return CRMScoringFeatureStatus(
        organizacion_id=organizacion_id,
        canal=canal,
        profiling_enabled=resolved_enabled,
        profiling_enabled_global=global_enabled,
        profiling_enabled_by_channel=by_channel,
    )


